insert into public.illness_scripts (id, version, status, reviewed_by, reviewed_at, content) values
  ('zorblax-syndrome', 1, 'approved', 'TEST', '2026-11-13T00:00:00Z', '{"kind":"disease","name":"Zorblax syndrome","aliases":["ZBX"],"systems":["general"],"rotation":["IM"],"confused_with":[{"script_id":"quellan-fever","how_to_tell_apart":"Quellan fever causes green nail beds and a normal blorp.","compare":[{"label":"Nails","text":"Blue nail beds","source_field":"key_findings.exam[0]"},{"label":"Blorp","text":"High","source_field":"key_findings.labs[0]"}]}],"pearls":["Zorblax syndrome never causes fever."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["key_findings.exam[0]","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1000000001"},{"kind":"note","id":"1000000002","rung":"management"}],"sources":[{"title":"Rounds test fixture (fictional)"}],"epidemiology":{"who":"Fictional adults over 40 (test fixture, not a real disease)","risk_factors":["glimmer exposure","night shift work","low blorp diet","family history"]},"pathophysiology":"Fictional autoimmune attack on the glimmer gland.","timeline":{"onset":"Subacute, over weeks","course":"Relapsing-remitting"},"key_findings":{"history":["purple fatigue","itchy elbows"],"exam":["blue nail beds"],"labs":["high serum blorp"],"imaging":["swollen glimmer gland on ultrasound"]},"diagnosis":{"confirmatory_tests":["anti-glimmer antibody"],"criteria":["serum blorp above 40 units with blue nail beds"]},"management":{"first_line":["zorbicillin"],"next_line":["plasma swap"]},"complications":["glimmer storm"]}'::jsonb),
  ('quellan-fever', 1, 'approved', 'TEST', '2026-11-13T00:00:00Z', '{"kind":"disease","name":"Quellan fever","aliases":["QF"],"systems":["general"],"rotation":["IM"],"confused_with":[{"script_id":"zorblax-syndrome","how_to_tell_apart":"Zorblax syndrome causes blue nail beds, high blorp and no fever.","compare":[{"label":"Nails","text":"Green nail beds","source_field":"key_findings.exam[0]"},{"label":"Blorp","text":"Normal","source_field":"key_findings.labs[0]"}]}],"pearls":[],"difficulty_tiers":{"MS1-2":[],"MS3":["key_findings.exam[0]"],"MS4":[]},"anki_refs":[],"sources":[{"title":"Rounds test fixture (fictional)"}],"epidemiology":{"who":"Fictional travelers (test fixture)","risk_factors":["quellan bites"]},"pathophysiology":"Fictional infection of the nail matrix.","timeline":{"onset":"Acute, over days","course":"Self-limited"},"key_findings":{"history":["fever","purple fatigue"],"exam":["green nail beds"],"labs":["normal blorp"],"imaging":[]},"diagnosis":{"confirmatory_tests":["quellan PCR"],"criteria":[]},"management":{"first_line":["supportive care"],"next_line":[]},"complications":[]}'::jsonb),
  ('ace-inhibitors', 1, 'in_review', null, null, '{"kind":"drug","name":"ACE inhibitors","aliases":["angiotensin-converting enzyme inhibitors"],"systems":["cardio","renal"],"rotation":[],"confused_with":[],"pearls":["A creatinine rise of up to 30% after starting is expected, and the drug can be continued.","The cough comes from bradykinin; switch to an ARB, which does not raise bradykinin.","ACE inhibitors slow diabetic kidney disease by dilating the efferent arteriole, which lowers pressure in the glomerulus."],"difficulty_tiers":{"MS1-2":["class","mechanism","adverse_effects"],"MS3":["indications","monitoring"],"MS4":["contraindications[3]","pearls[0]"]},"anki_refs":[],"sources":[{"title":"Katzung''s Basic and Clinical Pharmacology"},{"title":"Goodman & Gilman''s The Pharmacological Basis of Therapeutics"},{"title":"KDIGO 2024 Clinical Practice Guideline for the Evaluation and Management of Chronic Kidney Disease"}],"class":"Angiotensin-converting enzyme inhibitors","class_members":["lisinopril","enalapril","ramipril","captopril","benazepril"],"mechanism":"Block angiotensin-converting enzyme, so less angiotensin I becomes angiotensin II. Aldosterone falls, the efferent arteriole dilates, and bradykinin builds up because ACE also breaks bradykinin down.","pharmacokinetics":["most are prodrugs activated in the liver; captopril and lisinopril are not","cleared by the kidneys"],"indications":["hypertension","heart failure with reduced ejection fraction","after myocardial infarction","diabetic kidney disease and chronic kidney disease with proteinuria"],"adverse_effects":["dry cough","angioedema","hyperkalemia","acute rise in creatinine","hypotension after the first dose","teratogenic: fetal kidney damage"],"contraindications":["pregnancy","history of angioedema","bilateral renal artery stenosis","within 36 hours of sacubitril-valsartan"],"interactions":["potassium-sparing diuretics and potassium supplements raise potassium further","NSAIDs blunt the effect and add to kidney injury","raise lithium levels"],"monitoring":["potassium and creatinine 1 to 2 weeks after starting or raising the dose"],"overdose":{"features":["hypotension"],"treatment":["IV fluids"]}}'::jsonb),
  ('acute-coronary-syndrome', 1, 'in_review', null, null, '{"kind":"disease","name":"Acute coronary syndrome","aliases":["ACS","myocardial infarction"],"systems":["cardio"],"rotation":["IM","EM"],"confused_with":[{"script_id":"aortic-dissection","how_to_tell_apart":"Aortic dissection gives sudden tearing pain radiating to the back, a blood pressure difference between arms and a widened mediastinum; exclude it before giving anticoagulants.","compare":[{"label":"Pain","text":"Pressure, to arm or jaw","source_field":"key_findings.history[0]"},{"label":"Exam","text":"Often normal","source_field":"key_findings.exam[0]"},{"label":"First drug","text":"Aspirin","source_field":"management.first_line[0]"}]},{"script_id":"pulmonary-embolism","how_to_tell_apart":"PE causes pleuritic pain, hypoxemia and tachycardia, usually without ST elevation.","compare":[{"label":"Pain","text":"Pressure, to arm or jaw","source_field":"key_findings.history[0]"},{"label":"First test","text":"ECG within 10 minutes","source_field":"diagnosis.confirmatory_tests[0]"},{"label":"First drug","text":"Aspirin","source_field":"management.first_line[0]"}]}],"pearls":["Avoid nitrates in inferior MI with right ventricular involvement, or after a phosphodiesterase inhibitor such as sildenafil: they can cause severe hypotension."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1471899395392"},{"kind":"note","id":"1472320389702"},{"kind":"note","id":"1496961116835"},{"kind":"note","id":"1497314069507"},{"kind":"note","id":"1550527900362"},{"kind":"note","id":"1497804272202","rung":"recall"},{"kind":"note","id":"1543516065507","rung":"recall"},{"kind":"note","id":"1550522074335","rung":"recall"},{"kind":"note","id":"1471899090660","rung":"workup"},{"kind":"note","id":"1497804636687","rung":"workup"},{"kind":"note","id":"1550522074056","rung":"workup"},{"kind":"note","id":"1472747857568","rung":"management"},{"kind":"note","id":"1522940134564","rung":"management"},{"kind":"note","id":"1555271601101","rung":"management"}],"sources":[{"title":"2025 ACC/AHA/ACEP/NAEMSP/SCAI Guideline for the Management of Patients With Acute Coronary Syndromes"}],"epidemiology":{"who":"Adults with atherosclerotic risk factors","risk_factors":["smoking","diabetes","hypertension","hyperlipidemia","family history of premature coronary disease","older age"]},"pathophysiology":"Rupture or erosion of an atherosclerotic plaque triggers a thrombus that reduces or blocks coronary blood flow, causing myocardial ischemia or infarction.","timeline":{"onset":"Sudden, often at rest","course":"Heart muscle is lost with every minute of a complete occlusion"},"key_findings":{"history":["pressure-like chest pain radiating to the arm or jaw","dyspnea","diaphoresis","nausea"],"exam":["often normal","signs of heart failure or shock in large infarcts"],"labs":["rise and fall of high-sensitivity troponin","ECG: ST elevation in STEMI; ST depression or T-wave inversion in NSTE-ACS"],"imaging":["echocardiogram for wall motion abnormalities"]},"diagnosis":{"confirmatory_tests":["12-lead ECG within 10 minutes","high-sensitivity troponin, repeated"],"criteria":["STEMI: ST elevation in two contiguous leads","NSTEMI: troponin rise without ST elevation","unstable angina: ischemic symptoms without a troponin rise"]},"management":{"first_line":["aspirin","second antiplatelet agent (P2Y12 inhibitor such as ticagrelor)","anticoagulation with heparin","primary PCI within 90 minutes for STEMI"],"next_line":["fibrinolysis if PCI is not available within 120 minutes","high-intensity statin","beta-blocker if no heart failure or shock","nitroglycerin for ongoing pain"]},"complications":["arrhythmias","heart failure","cardiogenic shock","papillary muscle rupture","ventricular free wall rupture"]}'::jsonb),
  ('acute-ischemic-stroke', 1, 'in_review', null, null, '{"kind":"disease","name":"Acute ischemic stroke","aliases":["stroke","CVA"],"systems":["neuro"],"rotation":["IM","EM","neuro"],"confused_with":[],"pearls":["Blood pressure must be below 185/110 mmHg before thrombolysis."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1512752683399"},{"kind":"note","id":"1512955668550"},{"kind":"note","id":"1550409526747"},{"kind":"note","id":"1550450202537"},{"kind":"note","id":"1555754474939"},{"kind":"note","id":"1481771759221","rung":"recall"},{"kind":"note","id":"1512595785795","rung":"recall"},{"kind":"note","id":"1550694286485","rung":"recall"},{"kind":"note","id":"1472668510022","rung":"management"},{"kind":"note","id":"1481771888224","rung":"management"},{"kind":"note","id":"1481771899132","rung":"management"}],"sources":[{"title":"Guidelines for the Early Management of Patients With Acute Ischemic Stroke: 2019 Update (AHA/ASA)"}],"epidemiology":{"who":"Older adults with vascular risk factors","risk_factors":["hypertension","atrial fibrillation","diabetes","smoking","hyperlipidemia","prior stroke or TIA"]},"pathophysiology":"A thrombus or embolus blocks a brain artery; the ischemic penumbra around the core can be saved by fast reperfusion.","timeline":{"onset":"Sudden","course":"Brain tissue is lost each minute until reperfusion"},"key_findings":{"history":["sudden one-sided weakness or numbness","speech difficulty","facial droop","time last known well"],"exam":["focal neurologic deficit matching a vascular territory","NIH Stroke Scale to grade severity"],"labs":["fingerstick glucose to exclude hypoglycemia"],"imaging":["noncontrast CT head to exclude hemorrhage","CT angiography to find a large vessel occlusion"]},"diagnosis":{"confirmatory_tests":["noncontrast CT head","CT angiography"],"criteria":["sudden focal deficit with a vascular explanation and no hemorrhage on imaging"]},"management":{"first_line":["IV thrombolysis (alteplase or tenecteplase) within 4.5 hours of last known well","mechanical thrombectomy for large vessel occlusion, up to 24 hours in selected patients","check glucose before treatment"],"next_line":["aspirin within 24 to 48 hours if not thrombolysed","secondary prevention: antiplatelet, statin, and anticoagulation for atrial fibrillation"]},"complications":["hemorrhagic transformation","cerebral edema","aspiration pneumonia","dysphagia"]}'::jsonb),
  ('acute-kidney-injury', 1, 'in_review', null, null, '{"kind":"disease","name":"Acute kidney injury","aliases":["AKI","acute renal failure"],"systems":["renal"],"rotation":["IM"],"confused_with":[],"pearls":["Indications for urgent dialysis (AEIOU): acidosis, electrolytes (hyperkalemia), ingestions, overload and uremia."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1475353385337"},{"kind":"note","id":"1475353595370"},{"kind":"note","id":"1475353706251"},{"kind":"note","id":"1475353706252"},{"kind":"note","id":"1556663045381"}],"sources":[{"title":"KDIGO Clinical Practice Guideline for Acute Kidney Injury (2012)"}],"epidemiology":{"who":"Hospitalized adults, especially older patients and those with chronic kidney disease","risk_factors":["volume depletion","sepsis","nephrotoxic drugs","IV contrast","urinary obstruction","chronic kidney disease"]},"pathophysiology":"A sudden fall in glomerular filtration, classified as prerenal (low perfusion), intrinsic (most often acute tubular necrosis) or postrenal (obstruction).","timeline":{"onset":"Hours to days","course":"Often recovers once the cause is fixed; can progress to dialysis or chronic kidney disease"},"key_findings":{"history":["reduced urine output","recent vomiting, diarrhea or poor intake","new medications such as NSAIDs, ACE inhibitors or aminoglycosides"],"exam":["signs of volume depletion or overload","palpable bladder in obstruction"],"labs":["creatinine rise of 0.3 mg/dL or more within 48 hours","BUN-to-creatinine ratio above 20 in prerenal AKI","muddy brown granular casts in acute tubular necrosis","fractional excretion of sodium below 1% in prerenal AKI"],"imaging":["renal ultrasound to look for hydronephrosis"]},"diagnosis":{"confirmatory_tests":["serum creatinine","urine output","urinalysis with microscopy","renal ultrasound"],"criteria":["creatinine rise of 0.3 mg/dL or more within 48 hours","creatinine 1.5 times baseline or more within 7 days","urine output below 0.5 mL/kg/h for 6 hours"]},"management":{"first_line":["treat the cause","IV fluids if volume depleted","stop nephrotoxic drugs","relieve obstruction"],"next_line":["dialysis for refractory hyperkalemia, acidosis, volume overload, uremic complications or toxins","adjust drug doses for kidney function"]},"complications":["hyperkalemia","metabolic acidosis","volume overload","uremic pericarditis","progression to chronic kidney disease"]}'::jsonb),
  ('acute-pancreatitis', 1, 'in_review', null, null, '{"kind":"disease","name":"Acute pancreatitis","aliases":[],"systems":["gi"],"rotation":["IM","surgery"],"confused_with":[{"script_id":"diabetic-ketoacidosis","how_to_tell_apart":"DKA can cause abdominal pain and a mildly raised lipase, but it has high glucose, ketones and an anion gap acidosis, and the pain improves as the acidosis is treated.","compare":[{"label":"Key lab","text":"Lipase over 3x normal","source_field":"key_findings.labs[0]"},{"label":"Exam","text":"Epigastric tenderness","source_field":"key_findings.exam[0]"},{"label":"Treat","text":"Lactated Ringer''s","source_field":"management.first_line[0]"}]}],"pearls":["Gallstone pancreatitis is suggested by an ALT more than 3 times the upper limit of normal."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["key_findings.history[0]","diagnosis.criteria[0]","management.first_line"],"MS4":["pearls[0]","management.next_line[0]"]},"anki_refs":[{"kind":"note","id":"1495239550899"},{"kind":"note","id":"1495239811994"},{"kind":"note","id":"1511219527044"},{"kind":"note","id":"1511219634492"},{"kind":"note","id":"1535921440931"},{"kind":"note","id":"1482971305143","rung":"recall"},{"kind":"note","id":"1482971320837","rung":"recall"},{"kind":"note","id":"1482971441031","rung":"recall"},{"kind":"note","id":"1495670579999","rung":"management"},{"kind":"note","id":"1532131804405","rung":"management"},{"kind":"note","id":"1535304077148","rung":"management"}],"sources":[{"title":"American College of Gastroenterology Guideline: Management of Acute Pancreatitis (2024)"},{"title":"Classification of acute pancreatitis: revision of the Atlanta classification by international consensus (2012)"}],"epidemiology":{"who":"Adults; gallstones are the most common cause, then heavy alcohol use","risk_factors":["gallstones","alcohol","hypertriglyceridemia","post-ERCP","medications","hypercalcemia"]},"pathophysiology":"Premature activation of pancreatic enzymes (trypsin) inside the gland causes autodigestion and local inflammation, which can become a systemic inflammatory response.","timeline":{"onset":"Sudden, over hours","course":"Mild disease settles within a week; severe disease brings organ failure lasting over 48 hours and local complications"},"key_findings":{"history":["sudden epigastric pain radiating to the back","nausea and vomiting","recent heavy alcohol use or known gallstones"],"exam":["epigastric tenderness","tachycardia","flank or periumbilical bruising in severe disease"],"labs":["lipase more than 3 times the upper limit of normal","raised ALT in gallstone pancreatitis"],"imaging":["right upper quadrant ultrasound to look for gallstones","contrast CT only if the diagnosis is unclear or the patient is not improving"]},"diagnosis":{"confirmatory_tests":["serum lipase","right upper quadrant ultrasound"],"criteria":["two of three: typical epigastric pain, lipase more than 3 times the upper limit of normal, characteristic imaging findings"]},"management":{"first_line":["early goal-directed IV fluids with lactated Ringer''s","pain control","early oral feeding as tolerated"],"next_line":["cholecystectomy during the same admission for mild gallstone pancreatitis","ERCP within 24 hours if there is cholangitis","no prophylactic antibiotics"]},"complications":["pancreatic pseudocyst","walled-off necrosis","infected necrosis","ARDS","acute kidney injury"]}'::jsonb),
  ('acute-pyelonephritis', 1, 'in_review', null, null, '{"kind":"disease","name":"Acute pyelonephritis","aliases":["pyelonephritis","kidney infection"],"systems":["renal"],"rotation":["IM","EM","FM"],"confused_with":[],"pearls":["White blood cell casts in the urine point to the kidney (pyelonephritis) rather than the bladder."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1520885217485","rung":"recall"},{"kind":"note","id":"1547916133337","rung":"recall"},{"kind":"note","id":"1553043297138","rung":"recall"},{"kind":"note","id":"1543683644900","rung":"management"},{"kind":"note","id":"1547564850214","rung":"management"},{"kind":"note","id":"1553043297393","rung":"management"}],"sources":[{"title":"International Clinical Practice Guidelines for the Treatment of Acute Uncomplicated Cystitis and Pyelonephritis in Women (IDSA and ESCMID, 2010)"}],"epidemiology":{"who":"Mostly women; also men with urinary obstruction","risk_factors":["female sex","recent sexual intercourse","urinary obstruction or stones","pregnancy","diabetes","urinary catheter"]},"pathophysiology":"Bacteria, most often Escherichia coli, ascend from the bladder and infect the kidney.","timeline":{"onset":"Over 1 to 2 days","course":"Fever usually settles within 72 hours of antibiotics"},"key_findings":{"history":["fever and chills","flank pain","dysuria and frequency","nausea and vomiting"],"exam":["costovertebral angle tenderness","fever"],"labs":["pyuria","white blood cell casts","positive urine culture"],"imaging":["CT or ultrasound if there is no improvement after 48 to 72 hours, or obstruction is suspected"]},"diagnosis":{"confirmatory_tests":["urinalysis","urine culture before antibiotics"],"criteria":["flank pain or costovertebral angle tenderness with fever and pyuria"]},"management":{"first_line":["oral fluoroquinolone (ciprofloxacin) if local resistance is low and the patient is well","IV ceftriaxone if admitted"],"next_line":["tailor to culture results","imaging and drainage for obstruction or abscess"]},"complications":["sepsis","renal abscess","emphysematous pyelonephritis"]}'::jsonb),
  ('adrenal-insufficiency', 1, 'in_review', null, null, '{"kind":"disease","name":"Adrenal insufficiency","aliases":["Addison disease","adrenal crisis"],"systems":["endo"],"rotation":["IM"],"confused_with":[{"script_id":"septic-shock","how_to_tell_apart":"Septic shock also causes fluid-resistant hypotension with fever; adrenal crisis adds hyponatremia, hyperkalemia and hypoglycemia, and responds to hydrocortisone.","compare":[{"label":"Key lab","text":"Low morning cortisol","source_field":"key_findings.labs[2]"},{"label":"Clue","text":"Hyperpigmentation","source_field":"key_findings.exam[1]"},{"label":"Treat","text":"IV hydrocortisone","source_field":"management.first_line[0]"}]}],"pearls":["Hyperkalemia and hyperpigmentation point to primary disease; in secondary disease aldosterone is intact and ACTH is low."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1502236479001"},{"kind":"note","id":"1555720529080"},{"kind":"note","id":"1496623452372","rung":"recall"},{"kind":"note","id":"1502236802283","rung":"recall"},{"kind":"note","id":"1502560818022","rung":"recall"},{"kind":"note","id":"1532693062576","rung":"management"},{"kind":"note","id":"1552216700593","rung":"management"},{"kind":"note","id":"1555720467958","rung":"management"}],"sources":[{"title":"Diagnosis and Treatment of Primary Adrenal Insufficiency: An Endocrine Society Clinical Practice Guideline (2016)"}],"epidemiology":{"who":"Primary disease is usually autoimmune; secondary disease most often follows stopping long-term glucocorticoids","risk_factors":["autoimmune adrenalitis","abrupt withdrawal of long-term steroids","tuberculosis","adrenal hemorrhage","pituitary disease"]},"pathophysiology":"Primary disease destroys the adrenal cortex, losing cortisol and aldosterone; secondary disease lacks ACTH, losing cortisol only.","timeline":{"onset":"Insidious, or a sudden crisis during illness","course":"Needs lifelong replacement; a crisis is fatal without steroids"},"key_findings":{"history":["fatigue and weakness","weight loss","nausea, vomiting and abdominal pain","salt craving"],"exam":["hypotension","hyperpigmentation of skin and gums in primary disease"],"labs":["hyponatremia","hyperkalemia in primary disease","low morning cortisol","hypoglycemia"],"imaging":[]},"diagnosis":{"confirmatory_tests":["morning serum cortisol","ACTH stimulation test (cosyntropin)","plasma ACTH to separate primary from secondary disease"],"criteria":["a peak cortisol below 18 micrograms/dL after cosyntropin confirms adrenal insufficiency"]},"management":{"first_line":["adrenal crisis: IV hydrocortisone 100 mg and IV saline immediately","chronic: hydrocortisone replacement","fludrocortisone in primary disease"],"next_line":["double the steroid dose during illness (sick-day rules)","medical alert identification and an emergency injection kit"]},"complications":["adrenal crisis","shock","death"]}'::jsonb),
  ('alcohol-withdrawal', 1, 'in_review', null, null, '{"kind":"disease","name":"Alcohol withdrawal","aliases":["alcohol withdrawal syndrome","delirium tremens"],"systems":["psych","neuro"],"rotation":["IM","EM","psych"],"confused_with":[],"pearls":["Give thiamine before glucose in heavy drinkers to avoid precipitating Wernicke encephalopathy."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1485313510624"},{"kind":"note","id":"1505859856287"},{"kind":"note","id":"1557061576009"}],"sources":[{"title":"The ASAM Clinical Practice Guideline on Alcohol Withdrawal Management (2020)"}],"epidemiology":{"who":"People who drink heavily every day and stop or cut down, often on hospital admission","risk_factors":["heavy daily drinking","prior withdrawal seizures or delirium tremens","sudden abstinence","older age","acute medical illness"]},"pathophysiology":"Chronic alcohol enhances GABA and suppresses glutamate signalling; stopping leaves unopposed excitation.","timeline":{"onset":"Tremor from about 6 hours; seizures at 12 to 48 hours; delirium tremens at 48 to 96 hours","course":"Delirium tremens can be fatal"},"key_findings":{"history":["time of the last drink","tremor","anxiety","sweating","hallucinations"],"exam":["tremor","tachycardia","hypertension","diaphoresis","agitation or confusion in delirium tremens"],"labs":["hypokalemia","hypomagnesemia","hypophosphatemia","raised GGT","macrocytosis"],"imaging":[]},"diagnosis":{"confirmatory_tests":["clinical diagnosis","CIWA-Ar score to grade severity"],"criteria":["withdrawal symptoms after stopping or reducing heavy, prolonged drinking"]},"management":{"first_line":["benzodiazepines such as lorazepam or chlordiazepoxide, symptom-triggered by CIWA-Ar","thiamine before glucose","correct magnesium and potassium"],"next_line":["phenobarbital for benzodiazepine-resistant withdrawal","ICU for delirium tremens"]},"complications":["withdrawal seizures","delirium tremens","Wernicke encephalopathy","death"]}'::jsonb),
  ('aortic-dissection', 1, 'in_review', null, null, '{"kind":"disease","name":"Aortic dissection","aliases":["dissecting aorta"],"systems":["cardio"],"rotation":["IM","EM","surgery"],"confused_with":[{"script_id":"acute-coronary-syndrome","how_to_tell_apart":"ACS gives pressure-like pain with ECG changes and a troponin rise; dissection gives tearing pain to the back, unequal arm pressures and a widened mediastinum, and anticoagulation can be fatal.","compare":[{"label":"Pain","text":"Tearing, to the back","source_field":"key_findings.history[0]"},{"label":"Exam","text":"Arm BP gap over 20 mmHg","source_field":"key_findings.exam[0]"},{"label":"First drug","text":"IV beta-blocker","source_field":"management.first_line[0]"}]}],"pearls":["Give the beta-blocker before any vasodilator: lowering blood pressure alone causes reflex tachycardia that increases shear on the aorta."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1532186604247"},{"kind":"note","id":"1532189052771"},{"kind":"note","id":"1532189236664"},{"kind":"note","id":"1556206626632"},{"kind":"note","id":"1557012534276"}],"sources":[{"title":"2022 ACC/AHA Guideline for the Diagnosis and Management of Aortic Disease"}],"epidemiology":{"who":"Older adults with hypertension; younger patients with connective tissue disease","risk_factors":["hypertension","Marfan syndrome","bicuspid aortic valve","cocaine use","prior aortic surgery","pregnancy"]},"pathophysiology":"A tear in the aortic intima lets blood split the media, creating a false lumen that can extend, block branch arteries or rupture.","timeline":{"onset":"Sudden","course":"Type A (ascending aorta) is a surgical emergency with high early mortality"},"key_findings":{"history":["sudden severe tearing chest pain radiating to the back","syncope","stroke-like symptoms"],"exam":["blood pressure difference of more than 20 mmHg between arms","pulse deficit","new murmur of aortic regurgitation"],"labs":["D-dimer usually raised"],"imaging":["widened mediastinum on chest X-ray","CT angiography of the chest showing an intimal flap"]},"diagnosis":{"confirmatory_tests":["CT angiography of the chest","transesophageal echocardiogram if unstable"],"criteria":["Stanford type A involves the ascending aorta; type B does not"]},"management":{"first_line":["IV beta-blocker such as esmolol to lower heart rate and blood pressure","pain control","emergency surgery for type A"],"next_line":["add a vasodilator such as nicardipine after beta-blockade","medical management for uncomplicated type B","endovascular repair for complicated type B"]},"complications":["aortic rupture","cardiac tamponade","acute aortic regurgitation","stroke","mesenteric or limb ischemia"]}'::jsonb),
  ('aortic-stenosis', 1, 'in_review', null, null, '{"kind":"disease","name":"Aortic stenosis","aliases":["calcific aortic stenosis","aortic valve stenosis"],"systems":["cardio"],"rotation":["IM"],"confused_with":[{"script_id":"hypertrophic-cardiomyopathy","how_to_tell_apart":"Both cause a systolic ejection murmur, but the murmur of aortic stenosis radiates to the carotids and gets softer with Valsalva, while the murmur of hypertrophic cardiomyopathy gets louder with Valsalva or standing. Aortic stenosis is a disease of older adults; hypertrophic cardiomyopathy is inherited and shows up in the young.","compare":[{"label":"Murmur","text":"RUSB, radiates to carotids","source_field":"key_findings.exam[0]"},{"label":"Valsalva","text":"Softer","source_field":"pearls[0]"},{"label":"Who","text":"Older adults, calcified valve","source_field":"epidemiology.who"}]}],"pearls":["The murmur of aortic stenosis gets softer with Valsalva and standing, because less blood fills the ventricle.","The classic symptoms of severe aortic stenosis are syncope, angina and dyspnea from heart failure.","Severe aortic stenosis with GI bleeding from angiodysplasia is Heyde syndrome."],"difficulty_tiers":{"MS1-2":["pathophysiology","key_findings.exam[0]"],"MS3":["diagnosis.criteria","management.first_line"],"MS4":["management.next_line","pearls[2]"]},"anki_refs":[],"sources":[{"title":"2020 ACC/AHA Guideline for the Management of Patients With Valvular Heart Disease"},{"title":"2025 ESC/EACTS Guidelines for the management of valvular heart disease"}],"epidemiology":{"who":"Older adults with age-related calcification of a normal valve, and younger adults with a bicuspid valve","risk_factors":["older age","bicuspid aortic valve","rheumatic heart disease","chronic kidney disease","atherosclerotic risk factors"]},"pathophysiology":"The aortic valve calcifies and narrows, obstructing left ventricular outflow. The ventricle hypertrophies concentrically to keep up its output and eventually fails. Coronary flow cannot meet the thick wall''s oxygen demand, which causes angina.","timeline":{"onset":"Silent for decades; symptoms appear once the stenosis is severe","course":"Once symptoms start, survival without valve replacement is short"},"key_findings":{"history":["exertional dyspnea","angina","syncope on exertion","heart failure symptoms"],"exam":["harsh crescendo-decrescendo systolic murmur at the right upper sternal border radiating to the carotids","slow-rising, weak carotid pulse (pulsus parvus et tardus)","soft or absent second heart sound","sustained apex beat"],"labs":["BNP rises as the ventricle fails"],"imaging":["echocardiogram showing a calcified valve, a small valve area and a high gradient","ECG with left ventricular hypertrophy"]},"diagnosis":{"confirmatory_tests":["transthoracic echocardiogram"],"criteria":["Severe aortic stenosis: mean gradient 40 mmHg or more, peak velocity 4 m/s or more, or a valve area of 1 square centimeter or less"]},"management":{"first_line":["aortic valve replacement for severe stenosis with symptoms or an ejection fraction below 50%: transcatheter (TAVR) or surgical (SAVR)","TAVR is preferred for older patients and those at high surgical risk","serial echocardiograms while asymptomatic; earlier replacement is increasingly offered for severe disease"],"next_line":["balloon valvuloplasty as a bridge in unstable patients","cautious diuresis; avoid strong vasodilators, which can drop blood pressure"]},"complications":["heart failure","sudden cardiac death","GI bleeding from angiodysplasia (Heyde syndrome)","infective endocarditis"]}'::jsonb),
  ('asthma-exacerbation', 1, 'in_review', null, null, '{"kind":"disease","name":"Asthma exacerbation","aliases":["acute asthma","asthma attack"],"systems":["pulm"],"rotation":["IM","EM","peds"],"confused_with":[{"script_id":"copd-exacerbation","how_to_tell_apart":"COPD affects older smokers, and its airflow limitation persists between exacerbations; in asthma it is largely reversible.","compare":[{"label":"Who","text":"Any age, with asthma","source_field":"epidemiology.who"},{"label":"Clue","text":"Cough worse at night","source_field":"key_findings.history[3]"},{"label":"Oxygen target","text":"93 to 95%","source_field":"management.first_line[2]"}]}],"pearls":["A normal or rising PaCO2 during an asthma attack means the patient is tiring and may need intubation."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1473536778562"},{"kind":"note","id":"1474580971787"},{"kind":"note","id":"1495911001468"},{"kind":"note","id":"1539204159804"},{"kind":"note","id":"1550662680256"},{"kind":"note","id":"1495894152946","rung":"recall"},{"kind":"note","id":"1537631653103","rung":"recall"},{"kind":"note","id":"1550662682692","rung":"recall"}],"sources":[{"title":"Global Strategy for Asthma Management and Prevention (GINA 2024)"}],"epidemiology":{"who":"Children and adults with asthma, especially with poor control or prior severe attacks","risk_factors":["viral respiratory infection","allergen exposure","poor adherence to inhaled steroids","smoke exposure","exercise","cold air"]},"pathophysiology":"Airway inflammation, bronchospasm and mucus plugging cause reversible airflow obstruction and air trapping.","timeline":{"onset":"Over hours to days","course":"Usually responds to treatment; severe attacks can progress to respiratory failure"},"key_findings":{"history":["dyspnea","wheeze","chest tightness","cough, often worse at night"],"exam":["expiratory wheeze","tachypnea","accessory muscle use","silent chest in life-threatening attacks"],"labs":["peak expiratory flow below 50% of predicted in a severe attack","a normal or rising PaCO2 is a warning sign of fatigue"],"imaging":["chest X-ray only if pneumothorax or pneumonia is suspected"]},"diagnosis":{"confirmatory_tests":["peak expiratory flow","pulse oximetry","arterial blood gas in severe attacks"],"criteria":["acute worsening of symptoms and lung function from the patient''s usual status"]},"management":{"first_line":["inhaled short-acting beta-agonist (albuterol), repeated","systemic corticosteroids","oxygen to keep saturation 93 to 95%","ipratropium in severe attacks"],"next_line":["IV magnesium sulfate for severe attacks","ICU and intubation for respiratory failure"]},"complications":["respiratory failure","pneumothorax","death"]}'::jsonb),
  ('atrial-fibrillation', 1, 'in_review', null, null, '{"kind":"disease","name":"Atrial fibrillation","aliases":["AF","AFib"],"systems":["cardio"],"rotation":["IM","EM","FM"],"confused_with":[],"pearls":["Direct oral anticoagulants are preferred over warfarin, except with a mechanical heart valve or moderate to severe mitral stenosis."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.criteria[0]","management.first_line"],"MS4":["pearls[0]","management.next_line[1]"]},"anki_refs":[{"kind":"note","id":"1578765152246"},{"kind":"note","id":"1472147549163","rung":"recall"},{"kind":"note","id":"1550409526747","rung":"recall"},{"kind":"note","id":"1557341643876","rung":"recall"},{"kind":"note","id":"1497748713929","rung":"management"},{"kind":"note","id":"1532380404222","rung":"management"},{"kind":"note","id":"1555275580254","rung":"management"}],"sources":[{"title":"2023 ACC/AHA/ACCP/HRS Guideline for the Diagnosis and Management of Atrial Fibrillation"}],"epidemiology":{"who":"Mostly older adults; prevalence rises sharply with age","risk_factors":["older age","hypertension","heart failure","valvular heart disease","obesity","obstructive sleep apnea","alcohol","hyperthyroidism"]},"pathophysiology":"Disorganized atrial electrical activity, often triggered from the pulmonary veins, causes loss of atrial contraction and an irregular ventricular response; stasis in the left atrial appendage lets clot form and embolize.","timeline":{"onset":"Sudden or unnoticed","course":"Often starts paroxysmal and becomes persistent or permanent over time"},"key_findings":{"history":["palpitations","dyspnea","fatigue","lightheadedness","sometimes no symptoms"],"exam":["irregularly irregular pulse","variable intensity of S1"],"labs":["TSH to look for hyperthyroidism"],"imaging":["echocardiogram for chamber size, valves and ejection fraction"]},"diagnosis":{"confirmatory_tests":["12-lead ECG"],"criteria":["ECG: irregularly irregular rhythm with no discernible P waves"]},"management":{"first_line":["rate control with a beta-blocker or a nondihydropyridine calcium channel blocker","anticoagulation based on stroke risk (CHA2DS2-VASc)","synchronized cardioversion if hemodynamically unstable"],"next_line":["rhythm control with cardioversion, antiarrhythmic drugs or catheter ablation","if AF has lasted 48 hours or more or the duration is unknown, anticoagulate for 3 weeks before elective cardioversion or exclude clot with a transesophageal echocardiogram"]},"complications":["ischemic stroke","systemic embolism","tachycardia-induced cardiomyopathy","heart failure"]}'::jsonb),
  ('bacterial-meningitis', 1, 'in_review', null, null, '{"kind":"disease","name":"Bacterial meningitis","aliases":["meningitis"],"systems":["neuro"],"rotation":["IM","EM","peds","neuro"],"confused_with":[],"pearls":["Never delay antibiotics for a CT or lumbar puncture: take blood cultures and treat immediately."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1515891636007"},{"kind":"note","id":"1517169728142"},{"kind":"note","id":"1537556677772","rung":"recall"},{"kind":"note","id":"1550409495760","rung":"recall"},{"kind":"note","id":"1575344364515","rung":"recall"},{"kind":"note","id":"1537557489214","rung":"management"},{"kind":"note","id":"1555451147551","rung":"management"},{"kind":"note","id":"1556473561662","rung":"management"}],"sources":[{"title":"2016 ESCMID guideline: diagnosis and treatment of acute bacterial meningitis"},{"title":"IDSA Practice Guidelines for the Management of Bacterial Meningitis (2004)"}],"epidemiology":{"who":"Infants, older adults and the immunocompromised; outbreaks in college dormitories","risk_factors":["age over 50","immunosuppression","asplenia","cochlear implant","CSF leak","crowded living such as dormitories"]},"pathophysiology":"Bacteria, most often Streptococcus pneumoniae or Neisseria meningitidis in adults, invade the subarachnoid space and inflame the meninges.","timeline":{"onset":"Hours to a day","course":"Fatal without prompt antibiotics; survivors may have hearing loss or neurologic deficits"},"key_findings":{"history":["fever","headache","neck stiffness","confusion"],"exam":["nuchal rigidity","altered mental status","petechial or purpuric rash in meningococcal disease","Kernig and Brudzinski signs, which are insensitive"],"labs":["CSF: high neutrophils, high protein, low glucose","CSF Gram stain and culture"],"imaging":["CT head before lumbar puncture only with focal deficits, papilledema, seizures, reduced consciousness or immunocompromise"]},"diagnosis":{"confirmatory_tests":["lumbar puncture with CSF analysis","blood cultures"],"criteria":["CSF neutrophilic pleocytosis with low glucose and high protein"]},"management":{"first_line":["empiric ceftriaxone plus vancomycin","add ampicillin if over 50 or immunocompromised (to cover Listeria)","dexamethasone before or with the first antibiotic dose"],"next_line":["droplet precautions and prophylaxis for close contacts in meningococcal disease","tailor antibiotics to culture"]},"complications":["hearing loss","seizures","cerebral edema","death"]}'::jsonb),
  ('beta-blockers', 1, 'in_review', null, null, '{"kind":"drug","name":"Beta blockers","aliases":["beta-blockers","beta-adrenergic blockers"],"systems":["cardio"],"rotation":[],"confused_with":[],"pearls":["Most beta-1 selective blockers start with A to M (atenolol, bisoprolol, esmolol, metoprolol), plus nebivolol; nonselective ones start with N to Z (nadolol, propranolol, timolol).","Stopping a beta blocker suddenly can cause rebound tachycardia and angina.","Glucagon reverses beta blocker overdose because it raises cAMP in heart cells without using beta receptors."],"difficulty_tiers":{"MS1-2":["class","mechanism","adverse_effects"],"MS3":["indications","contraindications"],"MS4":["overdose.treatment","pearls[2]"]},"anki_refs":[],"sources":[{"title":"Katzung''s Basic and Clinical Pharmacology"},{"title":"Goodman & Gilman''s The Pharmacological Basis of Therapeutics"},{"title":"2022 AHA/ACC/HFSA Guideline for the Management of Heart Failure"}],"class":"Beta-adrenergic receptor antagonists (class II antiarrhythmics)","class_members":["metoprolol","atenolol","bisoprolol","esmolol","nebivolol","propranolol","nadolol","carvedilol","labetalol"],"mechanism":"Block beta-1 receptors in the heart, lowering heart rate, contractility and renin release, and slowing conduction through the AV node. Nonselective agents also block beta-2 receptors in the airways and vessels. Carvedilol and labetalol also block alpha-1 receptors.","pharmacokinetics":["esmolol is very short-acting and given IV","atenolol is cleared by the kidneys; metoprolol and propranolol by the liver","propranolol is lipophilic and crosses into the brain"],"indications":["angina","after myocardial infarction","heart failure with reduced ejection fraction (carvedilol, metoprolol succinate, bisoprolol)","rate control in atrial fibrillation","hypertension","hypertrophic cardiomyopathy","thyrotoxicosis symptoms","migraine prevention and essential tremor (propranolol)","variceal bleeding prevention (nonselective agents)"],"adverse_effects":["bradycardia","hypotension","AV block","bronchospasm, mostly with nonselective agents","fatigue","erectile dysfunction","masked signs of hypoglycemia, such as tremor and palpitations","worsening of acute decompensated heart failure"],"contraindications":["asthma, for nonselective agents","second- or third-degree AV block or symptomatic bradycardia","acute decompensated heart failure","vasospastic angina"],"interactions":["verapamil or diltiazem add to bradycardia and AV block"],"monitoring":["heart rate","blood pressure"],"overdose":{"features":["bradycardia","hypotension","hypoglycemia"],"treatment":["IV glucagon","atropine","high-dose insulin with glucose"]}}'::jsonb),
  ('cellulitis', 1, 'in_review', null, null, '{"kind":"disease","name":"Cellulitis","aliases":[],"systems":["derm"],"rotation":["IM","EM","FM"],"confused_with":[{"script_id":"deep-vein-thrombosis","how_to_tell_apart":"DVT causes swelling and calf pain without spreading redness or fever, and compression ultrasound shows a clot.","compare":[{"label":"Leg","text":"Warm, red, poorly defined","source_field":"key_findings.exam[0]"},{"label":"Test","text":"Clinical diagnosis","source_field":"diagnosis.confirmatory_tests[0]"},{"label":"Treat","text":"Cephalexin","source_field":"management.first_line[0]"}]}],"pearls":["Redness of both legs is rarely cellulitis; think of stasis dermatitis first."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1517003863108"},{"kind":"note","id":"1517003902640"},{"kind":"note","id":"1517087494979"},{"kind":"note","id":"1517087779618"},{"kind":"note","id":"1578854051059"}],"sources":[{"title":"Practice Guidelines for the Diagnosis and Management of Skin and Soft Tissue Infections: 2014 Update by the IDSA"}],"epidemiology":{"who":"Adults with breaks in the skin barrier, leg edema or obesity","risk_factors":["skin breaks such as cuts or tinea pedis","lymphedema","obesity","venous insufficiency","prior cellulitis","diabetes"]},"pathophysiology":"Bacterial infection of the dermis and subcutaneous tissue, most often from beta-hemolytic streptococci and less often from Staphylococcus aureus.","timeline":{"onset":"Over 1 to 3 days","course":"Improves within 48 to 72 hours of antibiotics"},"key_findings":{"history":["spreading redness","pain","fever in some"],"exam":["warm, red, tender skin with poorly defined borders","usually one leg","no fluctuance unless there is an abscess"],"labs":["blood cultures only if systemically unwell"],"imaging":["ultrasound if an abscess is suspected"]},"diagnosis":{"confirmatory_tests":["clinical diagnosis"],"criteria":["acute spreading erythema, warmth and tenderness, usually on one side"]},"management":{"first_line":["oral cephalexin for nonpurulent cellulitis","elevate the limb","treat tinea pedis or other entry points"],"next_line":["add MRSA coverage (trimethoprim-sulfamethoxazole or doxycycline) for purulent infection","IV cefazolin if systemically ill","incision and drainage for an abscess"]},"complications":["abscess","bacteremia","necrotizing fasciitis","recurrence"]}'::jsonb),
  ('cholesterol-synthesis', 1, 'in_review', null, null, '{"kind":"pathway","name":"Cholesterol synthesis","aliases":["mevalonate pathway"],"systems":["cardio","general"],"rotation":[],"confused_with":[],"pearls":["HMG-CoA is also made in mitochondria for ketone bodies; cholesterol synthesis uses HMG-CoA made in the cytosol.","The liver makes most of its cholesterol at night, so short-acting statins are taken in the evening.","Steroid hormones start when cholesterol is cleaved to pregnenolone."],"difficulty_tiers":{"MS1-2":["steps","rate_limiting_enzyme","regulation"],"MS3":["drug_targets"],"MS4":["deficiencies[0]","pearls[0]"]},"anki_refs":[],"sources":[{"title":"Lippincott Illustrated Reviews: Biochemistry"},{"title":"Harper''s Illustrated Biochemistry"}],"location":"Cytosol and smooth endoplasmic reticulum, mostly in liver cells","purpose":"Makes cholesterol from acetyl-CoA, for cell membranes, bile acids, steroid hormones and vitamin D.","steps":["acetyl-CoA to HMG-CoA by HMG-CoA synthase","HMG-CoA to mevalonate by HMG-CoA reductase","mevalonate to isoprene units (isopentenyl pyrophosphate)","isoprene units join to make squalene","squalene to lanosterol by squalene epoxidase and cyclase, then to cholesterol"],"rate_limiting_enzyme":"HMG-CoA reductase","regulation":["insulin activates HMG-CoA reductase","glucagon inhibits HMG-CoA reductase","low cell cholesterol turns on synthesis through SREBP","high cell cholesterol speeds the breakdown of HMG-CoA reductase"],"cofactors":["NADPH, from the pentose phosphate pathway"],"deficiencies":["Smith-Lemli-Opitz syndrome: 7-dehydrocholesterol reductase deficiency at the last step, with low cholesterol, high 7-dehydrocholesterol, intellectual disability and fused second and third toes"],"drug_targets":["statins inhibit HMG-CoA reductase","terbinafine inhibits squalene epoxidase in the fungal version of the pathway, which makes ergosterol"],"treatment":["Smith-Lemli-Opitz syndrome: dietary cholesterol supplementation"]}'::jsonb),
  ('clostridioides-difficile-infection', 1, 'in_review', null, null, '{"kind":"disease","name":"Clostridioides difficile infection","aliases":["C. diff","CDI"],"systems":["gi"],"rotation":["IM"],"confused_with":[],"pearls":["Alcohol hand rubs do not kill C. difficile spores; wash with soap and water."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1578670876178"},{"kind":"note","id":"1543274938312","rung":"recall"},{"kind":"note","id":"1555757715051","rung":"recall"},{"kind":"note","id":"1581107333267","rung":"recall"},{"kind":"note","id":"1495753784346","rung":"management"},{"kind":"note","id":"1523551767770","rung":"management"},{"kind":"note","id":"1543275630756","rung":"management"}],"sources":[{"title":"Clinical Practice Guideline by IDSA and SHEA: 2021 Focused Update Guidelines on Management of Clostridioides difficile Infection in Adults"}],"epidemiology":{"who":"Hospitalized and older adults, especially after antibiotics","risk_factors":["recent antibiotics","hospitalization","older age","proton pump inhibitors","immunosuppression"]},"pathophysiology":"Antibiotics disrupt the gut flora, letting toxin-producing C. difficile colonize the colon and cause colitis.","timeline":{"onset":"Days to weeks after antibiotics","course":"About 1 in 5 recur after treatment"},"key_findings":{"history":["three or more watery stools in 24 hours","abdominal cramping","recent antibiotics, especially clindamycin, fluoroquinolones or cephalosporins"],"exam":["abdominal tenderness","fever"],"labs":["leukocytosis, sometimes very high","raised creatinine in severe disease"],"imaging":["CT for suspected fulminant colitis or toxic megacolon"]},"diagnosis":{"confirmatory_tests":["stool test for C. difficile toxin or toxin gene (PCR)"],"criteria":["test only unformed stool, from patients with 3 or more unexplained loose stools in 24 hours","severe: white count of 15,000 or more, or creatinine above 1.5 mg/dL"]},"management":{"first_line":["oral fidaxomicin or oral vancomycin","stop the inciting antibiotic if possible","contact precautions and soap-and-water hand hygiene"],"next_line":["fulminant disease: oral vancomycin plus IV metronidazole, and a surgical consult","recurrence: fidaxomicin, bezlotoxumab or fecal microbiota transplant"]},"complications":["toxic megacolon","colonic perforation","recurrence","death"]}'::jsonb),
  ('community-acquired-pneumonia', 1, 'in_review', null, null, '{"kind":"disease","name":"Community-acquired pneumonia","aliases":["CAP"],"systems":["pulm"],"rotation":["IM","EM","FM"],"confused_with":[{"script_id":"pulmonary-embolism","how_to_tell_apart":"Pulmonary embolism also causes pleuritic pain, dyspnea and tachycardia, but usually has clear lungs and a near-normal chest X-ray despite hypoxemia; suspect it when there are risk factors for clots.","compare":[{"label":"Lungs","text":"Focal crackles","source_field":"key_findings.exam[0]"},{"label":"Imaging","text":"New focal infiltrate","source_field":"key_findings.imaging[0]"},{"label":"Treat","text":"Antibiotics","source_field":"management.first_line[0]"}]},{"script_id":"heart-failure-exacerbation","how_to_tell_apart":"Heart failure gives bilateral crackles, a raised JVP, leg edema and a high BNP, with bilateral interstitial edema and effusions on X-ray rather than a focal consolidation, and usually no fever.","compare":[{"label":"Lungs","text":"Focal crackles","source_field":"key_findings.exam[0]"},{"label":"Key lab","text":"Leukocytosis","source_field":"key_findings.labs[0]"},{"label":"Treat","text":"Antibiotics","source_field":"management.first_line[0]"}]},{"script_id":"copd-exacerbation","how_to_tell_apart":"A COPD exacerbation brings more dyspnea and sputum in a known smoker, without a new consolidation on chest X-ray.","compare":[{"label":"Exam","text":"Focal crackles","source_field":"key_findings.exam[0]"},{"label":"Chest X-ray","text":"New focal infiltrate","source_field":"key_findings.imaging[0]"},{"label":"Treat","text":"Antibiotics","source_field":"management.first_line[0]"}]}],"pearls":["CURB-65 (confusion, urea over 19 mg/dL, respiratory rate 30 or more, low blood pressure, age 65 or older) is a quick bedside guide to admission; the ATS/IDSA guideline prefers the Pneumonia Severity Index."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["key_findings.exam","diagnosis.confirmatory_tests","management.first_line[0]"],"MS4":["pearls[0]","management.next_line[0]"]},"anki_refs":[{"kind":"note","id":"1539882094287"},{"kind":"note","id":"1556196826608"},{"kind":"note","id":"1556924270114"},{"kind":"note","id":"1569457354070"},{"kind":"note","id":"1569458111557"},{"kind":"note","id":"1474503849368","rung":"recall"},{"kind":"note","id":"1504659390894","rung":"recall"},{"kind":"note","id":"1550712326734","rung":"recall"},{"kind":"note","id":"1495908532054","rung":"management"},{"kind":"note","id":"1496497550431","rung":"management"},{"kind":"note","id":"1496498154874","rung":"management"}],"sources":[{"title":"Diagnosis and Treatment of Adults with Community-acquired Pneumonia: An Official Clinical Practice Guideline of the ATS and IDSA (2019)"}],"epidemiology":{"who":"Adults living in the community; risk rises with age and chronic lung disease","risk_factors":["age 65 or older","smoking","COPD","alcohol use disorder","immunosuppression"]},"pathophysiology":"Infection of the lung parenchyma, usually after aspiration of upper airway organisms. Streptococcus pneumoniae is the most common cause; others include Haemophilus influenzae, Mycoplasma pneumoniae, respiratory viruses, Staphylococcus aureus and Legionella.","timeline":{"onset":"Acute, over a few days","course":"Most patients improve within 48 to 72 hours of appropriate antibiotics"},"key_findings":{"history":["fever","cough with sputum","pleuritic chest pain","dyspnea"],"exam":["focal crackles","bronchial breath sounds","dullness to percussion","tachypnea"],"labs":["leukocytosis","hypoxemia"],"imaging":["chest X-ray showing a new lobar or focal infiltrate"]},"diagnosis":{"confirmatory_tests":["chest X-ray"],"criteria":["compatible symptoms plus a new infiltrate on chest imaging"]},"management":{"first_line":["outpatient without comorbidities: amoxicillin or doxycycline (a macrolide only where pneumococcal macrolide resistance is below 25%)","outpatient with comorbidities: amoxicillin-clavulanate or a cephalosporin plus a macrolide or doxycycline, or a respiratory fluoroquinolone alone","inpatient, not severe: ceftriaxone plus azithromycin, or a respiratory fluoroquinolone alone"],"next_line":["add MRSA or Pseudomonas coverage only with prior isolation of those organisms or other validated risk factors","ICU admission for severe pneumonia"]},"complications":["parapneumonic effusion","empyema","sepsis","ARDS","lung abscess"]}'::jsonb),
  ('copd-exacerbation', 1, 'in_review', null, null, '{"kind":"disease","name":"COPD exacerbation","aliases":["acute exacerbation of COPD","AECOPD"],"systems":["pulm"],"rotation":["IM","EM"],"confused_with":[{"script_id":"community-acquired-pneumonia","how_to_tell_apart":"Pneumonia adds fever and a new consolidation on chest X-ray; a COPD exacerbation has no new infiltrate.","compare":[{"label":"Exam","text":"Wheeze, long expiration","source_field":"key_findings.exam[0]"},{"label":"Chest X-ray","text":"To exclude pneumonia","source_field":"key_findings.imaging[0]"},{"label":"Treat","text":"Albuterol with ipratropium","source_field":"management.first_line[0]"}]},{"script_id":"heart-failure-exacerbation","how_to_tell_apart":"Heart failure gives a raised JVP, leg edema, a high BNP and pulmonary edema on chest X-ray.","compare":[{"label":"Exam","text":"Wheeze, long expiration","source_field":"key_findings.exam[0]"},{"label":"Key test","text":"Blood gas: high CO2","source_field":"key_findings.labs[0]"},{"label":"Treat","text":"Albuterol with ipratropium","source_field":"management.first_line[0]"}]},{"script_id":"asthma-exacerbation","how_to_tell_apart":"Asthma usually starts younger, often without a smoking history, and its airflow obstruction is largely reversible between attacks.","compare":[{"label":"Who","text":"Long smoking history","source_field":"epidemiology.who"},{"label":"Clue","text":"More purulent sputum","source_field":"key_findings.history[2]"},{"label":"Oxygen target","text":"88 to 92%","source_field":"management.first_line[3]"}]}],"pearls":["Target oxygen saturation 88 to 92% in COPD; high-flow oxygen can worsen hypercapnia."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1473623659476","rung":"recall"},{"kind":"note","id":"1496356970450","rung":"recall"},{"kind":"note","id":"1556994133668","rung":"recall"},{"kind":"note","id":"1545942903602","rung":"management"},{"kind":"note","id":"1550662680256","rung":"management"},{"kind":"note","id":"1555373219232","rung":"management"}],"sources":[{"title":"Global Strategy for the Diagnosis, Management, and Prevention of COPD (GOLD 2025 Report)"}],"epidemiology":{"who":"Adults with COPD, usually with a long smoking history","risk_factors":["viral respiratory infection","bacterial infection","air pollution","stopping inhalers"]},"pathophysiology":"Airway inflammation, usually triggered by infection, worsens airflow limitation and air trapping, raising the work of breathing and causing hypoxemia and sometimes hypercapnia.","timeline":{"onset":"Over days","course":"Most recover over 1 to 2 weeks; each exacerbation speeds the decline in lung function"},"key_findings":{"history":["worsening dyspnea","increased sputum volume","increased sputum purulence","cough"],"exam":["wheeze and prolonged expiration","accessory muscle use","pursed-lip breathing"],"labs":["arterial blood gas: hypercapnia and respiratory acidosis in severe cases"],"imaging":["chest X-ray to exclude pneumonia, pneumothorax or heart failure"]},"diagnosis":{"confirmatory_tests":["clinical diagnosis","arterial blood gas","chest X-ray"],"criteria":["acute worsening of dyspnea, cough or sputum beyond day-to-day variation"]},"management":{"first_line":["short-acting bronchodilators (albuterol with ipratropium)","systemic corticosteroids for 5 days","antibiotics when sputum purulence increases","controlled oxygen targeting saturation 88 to 92%"],"next_line":["noninvasive ventilation for hypercapnic respiratory acidosis","intubation if noninvasive ventilation fails"]},"complications":["hypercapnic respiratory failure","pneumothorax","death"]}'::jsonb),
  ('decompensated-cirrhosis', 1, 'in_review', null, null, '{"kind":"disease","name":"Decompensated cirrhosis","aliases":["cirrhosis","end-stage liver disease"],"systems":["gi"],"rotation":["IM"],"confused_with":[],"pearls":["Spontaneous bacterial peritonitis is diagnosed by an ascitic neutrophil count of 250 cells/mm3 or more."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1486522758122"},{"kind":"note","id":"1486522767302"},{"kind":"note","id":"1486591126064"},{"kind":"note","id":"1495561175263"},{"kind":"note","id":"1531956908372"},{"kind":"note","id":"1495497512091","rung":"recall"},{"kind":"note","id":"1567452654959","rung":"recall"},{"kind":"note","id":"1567452654960","rung":"recall"},{"kind":"note","id":"1557251726524","rung":"management"},{"kind":"note","id":"1580013594763","rung":"management"},{"kind":"note","id":"1580014252557","rung":"management"}],"sources":[{"title":"AASLD Practice Guidance: Diagnosis, Evaluation, and Management of Ascites, Spontaneous Bacterial Peritonitis and Hepatorenal Syndrome (2021)"},{"title":"Baveno VII: Renewing consensus in portal hypertension (2022)"}],"epidemiology":{"who":"Adults with chronic liver disease","risk_factors":["alcohol-related liver disease","chronic hepatitis C","chronic hepatitis B","metabolic dysfunction-associated steatotic liver disease"]},"pathophysiology":"Chronic liver injury causes fibrosis and portal hypertension, leading to ascites, varices and loss of the liver''s synthetic and detoxifying function.","timeline":{"onset":"Develops over years; decompensation can be sudden","course":"Decompensation marks a sharp fall in survival; transplant is the cure"},"key_findings":{"history":["abdominal swelling","jaundice","confusion","vomiting blood or black stools"],"exam":["ascites","jaundice","spider angiomas","palmar erythema","asterixis"],"labs":["low albumin","prolonged INR","raised bilirubin","low platelets"],"imaging":["ultrasound: nodular liver, splenomegaly, ascites"]},"diagnosis":{"confirmatory_tests":["diagnostic paracentesis for new ascites or any admission with ascites","serum-ascites albumin gradient"],"criteria":["decompensation means ascites, variceal bleeding, hepatic encephalopathy or jaundice","a serum-ascites albumin gradient of 1.1 g/dL or more means portal hypertension"]},"management":{"first_line":["sodium restriction and diuretics (spironolactone with furosemide) for ascites","lactulose for hepatic encephalopathy","nonselective beta-blocker such as carvedilol to prevent variceal bleeding"],"next_line":["large-volume paracentesis with albumin for tense ascites","add rifaximin to lactulose","refer for liver transplant evaluation"]},"complications":["spontaneous bacterial peritonitis","hepatorenal syndrome","variceal bleeding","hepatic encephalopathy","hepatocellular carcinoma"]}'::jsonb),
  ('deep-vein-thrombosis', 1, 'in_review', null, null, '{"kind":"disease","name":"Deep vein thrombosis","aliases":["DVT"],"systems":["heme_onc","cardio"],"rotation":["IM","EM","surgery"],"confused_with":[{"script_id":"cellulitis","how_to_tell_apart":"Cellulitis gives warm, red, tender skin with a spreading edge and often fever; DVT gives swelling and calf pain, and ultrasound shows a noncompressible vein.","compare":[{"label":"Leg","text":"Pitting edema","source_field":"key_findings.exam[1]"},{"label":"Test","text":"Compression ultrasound","source_field":"diagnosis.confirmatory_tests[0]"},{"label":"Treat","text":"DOAC for 3+ months","source_field":"management.first_line[0]"}]},{"script_id":"pulmonary-embolism","how_to_tell_apart":"PE adds dyspnea, pleuritic pain and hypoxemia; they are the same disease, so look for both.","compare":[{"label":"Symptom","text":"One swollen leg","source_field":"key_findings.history[0]"},{"label":"Test","text":"Compression ultrasound","source_field":"diagnosis.confirmatory_tests[0]"},{"label":"Treat","text":"DOAC for 3+ months","source_field":"management.first_line[0]"}]}],"pearls":["Virchow''s triad: venous stasis, endothelial injury and hypercoagulability."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1511025803136"},{"kind":"note","id":"1511025895605"},{"kind":"note","id":"1511025928050"},{"kind":"note","id":"1511028541153"},{"kind":"note","id":"1549586054765","rung":"recall"},{"kind":"note","id":"1550708813822","rung":"recall"},{"kind":"note","id":"1557843697920","rung":"recall"},{"kind":"note","id":"1474340749040","rung":"management"},{"kind":"note","id":"1511028698049","rung":"management"},{"kind":"note","id":"1532736174421","rung":"management"}],"sources":[{"title":"Antithrombotic Therapy for VTE Disease: Second Update of the CHEST Guideline and Expert Panel Report (2021)"}],"epidemiology":{"who":"Adults with risk factors for venous thromboembolism","risk_factors":["recent surgery","immobilization","active cancer","prior VTE","estrogen use or pregnancy","inherited thrombophilia"]},"pathophysiology":"Venous stasis, endothelial injury and hypercoagulability (Virchow''s triad) lead to thrombus in the deep veins, usually of the leg.","timeline":{"onset":"Over days","course":"Can embolize to the lungs; may leave post-thrombotic syndrome"},"key_findings":{"history":["unilateral leg swelling","calf pain"],"exam":["calf swelling more than 3 cm compared with the other leg","pitting edema of one leg","tenderness along the deep veins"],"labs":["raised D-dimer, useful to rule out DVT when pretest probability is low"],"imaging":["compression ultrasound showing a noncompressible vein"]},"diagnosis":{"confirmatory_tests":["compression ultrasound","D-dimer to rule out DVT when the Wells score is low"],"criteria":["the Wells score estimates pretest probability"]},"management":{"first_line":["anticoagulation with a direct oral anticoagulant such as apixaban or rivaroxaban for at least 3 months"],"next_line":["low-molecular-weight heparin in pregnancy","IVC filter only if anticoagulation is contraindicated"]},"complications":["pulmonary embolism","post-thrombotic syndrome","phlegmasia cerulea dolens"]}'::jsonb),
  ('diabetic-ketoacidosis', 1, 'in_review', null, null, '{"kind":"disease","name":"Diabetic ketoacidosis","aliases":["DKA"],"systems":["endo"],"rotation":["IM","EM"],"confused_with":[{"script_id":"acute-pancreatitis","how_to_tell_apart":"DKA causes abdominal pain and can raise lipase, but the labs show an anion gap acidosis with high ketones, and the pain eases as the acidosis is corrected; in pancreatitis the pain persists and imaging shows an inflamed pancreas.","compare":[{"label":"Key lab","text":"Anion gap acidosis","source_field":"key_findings.labs[1]"},{"label":"Exam","text":"Kussmaul breathing","source_field":"key_findings.exam[0]"},{"label":"Treat","text":"IV insulin infusion","source_field":"management.first_line[1]"}]},{"script_id":"hyperosmolar-hyperglycemic-state","how_to_tell_apart":"HHS has much higher glucose and osmolality with little or no ketosis or acidosis, and develops over days rather than hours.","compare":[{"label":"Glucose","text":"Usually over 250 mg/dL","source_field":"key_findings.labs[0]"},{"label":"Acidosis","text":"Anion gap acidosis","source_field":"key_findings.labs[1]"},{"label":"Ketones","text":"High beta-hydroxybutyrate","source_field":"key_findings.labs[2]"}]}],"pearls":["Check potassium before starting insulin: if it is below 3.5 mEq/L, replace it first and hold insulin, because insulin drives potassium into cells."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["key_findings.exam[0]","management.first_line","diagnosis.criteria"],"MS4":["pearls[0]","management.next_line"]},"anki_refs":[{"kind":"note","id":"1462327211125","rung":"recall"},{"kind":"note","id":"1502564341435","rung":"recall"},{"kind":"note","id":"1502845294644","rung":"recall"},{"kind":"note","id":"1462327382493","rung":"management"},{"kind":"note","id":"1552260881200","rung":"management"},{"kind":"note","id":"1568856424118","rung":"management"}],"sources":[{"title":"Hyperglycemic Crises in Adults With Diabetes: A Consensus Report (Diabetes Care, 2024)"}],"epidemiology":{"who":"Mostly people with type 1 diabetes, often as the first presentation; also type 2 diabetes under acute stress or on SGLT2 inhibitors","risk_factors":["infection","insulin omission","new-onset diabetes","SGLT2 inhibitors","myocardial infarction","pancreatitis"]},"pathophysiology":"Insulin deficiency plus excess counterregulatory hormones (glucagon, cortisol, catecholamines) drive lipolysis and hepatic ketogenesis, causing an anion gap metabolic acidosis. Hyperglycemia causes an osmotic diuresis with volume depletion and a total-body potassium deficit.","timeline":{"onset":"Develops over hours, usually less than 24 hours","course":"Resolves over about a day with fluids, insulin and potassium; can recur if the precipitant is not treated"},"key_findings":{"history":["polyuria and polydipsia","nausea and vomiting","abdominal pain"],"exam":["Kussmaul respirations (deep, rapid breathing)","fruity (acetone) breath","signs of volume depletion: tachycardia, dry mucous membranes"],"labs":["glucose usually above 250 mg/dL","anion gap metabolic acidosis","raised serum beta-hydroxybutyrate","serum potassium often normal or high despite a total-body deficit"],"imaging":[]},"diagnosis":{"confirmatory_tests":["serum beta-hydroxybutyrate","venous blood gas","basic metabolic panel with anion gap"],"criteria":["glucose of 200 mg/dL or more, or known diabetes","ketosis: beta-hydroxybutyrate of 3.0 mmol/L or more, or urine ketones 2+ or more","acidosis: pH below 7.3 and/or bicarbonate below 18 mEq/L"]},"management":{"first_line":["IV isotonic fluids","IV insulin infusion","potassium replacement"],"next_line":["add dextrose to the fluids when glucose falls below 250 mg/dL","bicarbonate only if pH is below 7.0","overlap subcutaneous basal insulin by 1 to 2 hours before stopping the infusion","treat the precipitant"]},"complications":["hypokalemia","hypoglycemia","cerebral edema, mainly in children","recurrence after stopping the infusion too early"]}'::jsonb),
  ('enterococcus', 1, 'in_review', null, null, '{"kind":"bug","name":"Enterococcus","aliases":["enterococci","Enterococcus faecalis","Enterococcus faecium"],"systems":["cardio","renal"],"rotation":[],"confused_with":[{"script_id":"viridans-streptococci","how_to_tell_apart":"Both cause subacute endocarditis. Enterococci grow in 6.5% salt, come from the gut and urinary tract and follow GI or urinary procedures; viridans streptococci are alpha-hemolytic, come from the mouth and follow dental work.","compare":[{"label":"Gram stain","text":"Cocci in pairs, short chains","source_field":"morphology"},{"label":"Source","text":"Gut flora","source_field":"transmission[0]"},{"label":"Key test","text":"Grows in 6.5% NaCl","source_field":"lab_features[1]"}]},{"script_id":"staphylococcus-aureus","how_to_tell_apart":"Enterococci grow in pairs and short chains, are catalase-negative and grow in 6.5% salt; S. aureus grows in clusters and is catalase- and coagulase-positive.","compare":[{"label":"Gram stain","text":"Cocci in pairs, short chains","source_field":"morphology"},{"label":"Course","text":"Subacute endocarditis","source_field":"diseases[1]"},{"label":"Key test","text":"Grows in 6.5% NaCl","source_field":"lab_features[1]"}]}],"pearls":["Enterococci are naturally resistant to all cephalosporins, so ceftriaxone alone never covers them.","Enterococcal endocarditis needs two drugs; ampicillin plus ceftriaxone works without the kidney toxicity of gentamicin.","VRE is most often Enterococcus faecium; E. faecalis is usually ampicillin-susceptible."],"difficulty_tiers":{"MS1-2":["morphology","lab_features"],"MS3":["diseases","treatment[0]"],"MS4":["treatment[1]","pearls[1]"]},"anki_refs":[],"sources":[{"title":"Sherris & Ryan''s Medical Microbiology"},{"title":"2023 ESC Guidelines for the management of endocarditis"}],"morphology":"Gram-positive cocci in pairs and short chains","lab_features":["catalase-negative","grows in 6.5% NaCl","hydrolyzes bile esculin","usually gamma-hemolytic (no hemolysis)","Lancefield group D"],"transmission":["normal flora of the gut","spreads in hospitals on hands and equipment","enters through the urinary tract, the bowel or catheters"],"virulence_factors":["intrinsic resistance to cephalosporins","acquired vancomycin resistance (VRE), mostly in E. faecium","biofilm on catheters and devices"],"diseases":["urinary tract infections, often catheter-related","subacute endocarditis, often in older adults after GI or urinary procedures","biliary and intra-abdominal infections","bacteremia from intravenous lines"],"diagnosis":["blood and urine cultures","growth in 6.5% NaCl and bile esculin hydrolysis in the lab","susceptibility testing for ampicillin and vancomycin"],"treatment":["ampicillin for susceptible strains","endocarditis: ampicillin plus ceftriaxone, or ampicillin plus gentamicin","VRE: linezolid or daptomycin","vancomycin for ampicillin-resistant, vancomycin-susceptible strains"],"prevention":["hand hygiene and contact precautions for VRE","removing catheters early"]}'::jsonb),
  ('essential-hypertension', 1, 'in_review', null, null, '{"kind":"disease","name":"Essential hypertension","aliases":["primary hypertension","high blood pressure"],"systems":["cardio"],"rotation":["IM","FM"],"confused_with":[],"pearls":["Never combine an ACE inhibitor with an ARB.","Resistant hypertension is blood pressure above goal despite three drugs, one of them a diuretic.","Hypertension in a young person, or with a low potassium, should prompt a search for a secondary cause such as primary hyperaldosteronism."],"difficulty_tiers":{"MS1-2":["pathophysiology","epidemiology.who"],"MS3":["diagnosis.criteria","management.first_line"],"MS4":["management.next_line","pearls[1]"]},"anki_refs":[],"sources":[{"title":"2025 AHA/ACC Guideline for the Prevention, Detection, Evaluation, and Management of High Blood Pressure in Adults"},{"title":"2024 ESC Guidelines for the management of elevated blood pressure and hypertension"}],"epidemiology":{"who":"Adults, more often with age; about 90% of hypertension has no single identifiable cause","risk_factors":["older age","family history","obesity","high sodium intake","physical inactivity","excess alcohol","Black ancestry"]},"pathophysiology":"Blood pressure rises from a mix of genetic and environmental factors: more sympathetic tone, renin-angiotensin-aldosterone activity, sodium retention and stiffer arteries. Over years it damages the heart, kidneys, brain and eyes.","timeline":{"onset":"Silent; usually found on screening","course":"Lifelong; untreated, it raises the risk of stroke, heart attack, heart failure and kidney disease"},"key_findings":{"history":["usually no symptoms","headache only when blood pressure is very high"],"exam":["blood pressure of 130/80 mmHg or higher on repeated readings","hypertensive retinopathy: arteriovenous nicking and cotton wool spots","left ventricular heave in long-standing disease"],"labs":["basic metabolic panel with creatinine and potassium","urinalysis and urine albumin","fasting glucose or HbA1c and a lipid panel"],"imaging":["ECG to look for left ventricular hypertrophy"]},"diagnosis":{"confirmatory_tests":["repeated office readings confirmed with ambulatory or home blood pressure monitoring"],"criteria":["AHA/ACC 2025: stage 1 hypertension is 130 to 139 systolic or 80 to 89 diastolic","AHA/ACC 2025: stage 2 hypertension is 140 systolic or 90 diastolic and above"]},"management":{"first_line":["lifestyle: weight loss, DASH diet, less salt, exercise and less alcohol","first-line drug classes: thiazide diuretic, ACE inhibitor, ARB or dihydropyridine calcium channel blocker","ACE inhibitor or ARB when there is diabetes with albuminuria or chronic kidney disease","a target under 130/80 for most adults"],"next_line":["stage 2: start two first-line classes, ideally as a single-pill combination","add spironolactone for resistant hypertension","look for a secondary cause when hypertension is resistant or starts young"]},"complications":["stroke","coronary artery disease","heart failure","chronic kidney disease","aortic dissection","hypertensive retinopathy"]}'::jsonb),
  ('heart-failure-exacerbation', 1, 'in_review', null, null, '{"kind":"disease","name":"Acute decompensated heart failure","aliases":["heart failure exacerbation","ADHF","CHF exacerbation"],"systems":["cardio"],"rotation":["IM","EM"],"confused_with":[{"script_id":"community-acquired-pneumonia","how_to_tell_apart":"Pneumonia usually brings fever, productive cough and a focal consolidation; heart failure gives bilateral crackles, a raised JVP, leg edema and a high BNP.","compare":[{"label":"Lungs","text":"Bibasilar crackles","source_field":"key_findings.exam[1]"},{"label":"Key lab","text":"Raised BNP","source_field":"key_findings.labs[0]"},{"label":"Treat","text":"IV loop diuretic","source_field":"management.first_line[0]"}]},{"script_id":"copd-exacerbation","how_to_tell_apart":"A COPD exacerbation gives wheeze and more sputum in a smoker, without a raised JVP, leg edema or a high BNP.","compare":[{"label":"Exam","text":"Raised JVP","source_field":"key_findings.exam[0]"},{"label":"Key test","text":"Raised BNP","source_field":"key_findings.labs[0]"},{"label":"Treat","text":"IV loop diuretic","source_field":"management.first_line[0]"}]}],"pearls":["The first IV loop diuretic dose should equal or exceed the patient''s total daily oral dose."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["key_findings.exam","diagnosis.confirmatory_tests","management.first_line[0]"],"MS4":["pearls[0]","management.next_line[0]"]},"anki_refs":[{"kind":"note","id":"1557777121517"},{"kind":"note","id":"1570070676637"},{"kind":"note","id":"1471547618307","rung":"recall"},{"kind":"note","id":"1497722931967","rung":"recall"},{"kind":"note","id":"1539463025075","rung":"recall"},{"kind":"note","id":"1497308773697","rung":"workup"},{"kind":"note","id":"1550690801047","rung":"workup"},{"kind":"note","id":"1579476253074","rung":"workup"},{"kind":"note","id":"1477447145086","rung":"management"},{"kind":"note","id":"1497732761695","rung":"management"},{"kind":"note","id":"1555286309380","rung":"management"}],"sources":[{"title":"2022 AHA/ACC/HFSA Guideline for the Management of Heart Failure"}],"epidemiology":{"who":"Adults with known chronic heart failure, with reduced or preserved ejection fraction","risk_factors":["high salt intake","medication nonadherence","myocardial ischemia","atrial fibrillation","uncontrolled hypertension","infection","NSAIDs"]},"pathophysiology":"Worsening cardiac function or a precipitant raises left-sided filling pressures, causing pulmonary congestion, while sodium and water retention cause systemic venous congestion.","timeline":{"onset":"Usually over days, sometimes hours","course":"Most improve with diuresis over several days; each admission marks a worse long-term prognosis"},"key_findings":{"history":["worsening dyspnea","orthopnea","paroxysmal nocturnal dyspnea","weight gain","leg swelling"],"exam":["raised JVP","bibasilar crackles","S3 gallop","pitting edema"],"labs":["raised BNP or NT-proBNP","troponin may be mildly raised"],"imaging":["chest X-ray: pulmonary vascular congestion, interstitial edema, Kerley B lines, pleural effusions","echocardiogram to assess ejection fraction"]},"diagnosis":{"confirmatory_tests":["BNP or NT-proBNP","echocardiogram","chest X-ray"],"criteria":["clinical diagnosis: symptoms and signs of congestion, supported by a raised natriuretic peptide"]},"management":{"first_line":["IV loop diuretics such as furosemide","supplemental oxygen if hypoxemic","treat the precipitant"],"next_line":["add a thiazide-type diuretic such as metolazone if diuresis is inadequate","noninvasive ventilation for respiratory distress","vasodilators such as nitroglycerin if hypertensive","inotropes for low output with hypoperfusion"]},"complications":["cardiogenic shock","acute kidney injury","arrhythmias","hypokalemia from diuresis"]}'::jsonb),
  ('heart-failure', 1, 'in_review', null, null, '{"kind":"disease","name":"Chronic heart failure","aliases":["heart failure","congestive heart failure"],"systems":["cardio"],"rotation":["IM"],"confused_with":[],"pearls":["The beta blockers proven to lower mortality in HFrEF are carvedilol, metoprolol succinate and bisoprolol.","An S3 gallop signals volume overload; an S4 signals a stiff ventricle.","SGLT2 inhibitors cut heart failure hospitalizations whether or not the patient has diabetes."],"difficulty_tiers":{"MS1-2":["pathophysiology","key_findings.exam"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["management.next_line","pearls[0]"]},"anki_refs":[],"sources":[{"title":"2022 AHA/ACC/HFSA Guideline for the Management of Heart Failure"},{"title":"2023 Focused Update of the 2021 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure"}],"epidemiology":{"who":"Older adults, most often after coronary disease or long-standing hypertension","risk_factors":["coronary artery disease","hypertension","diabetes","obesity","valvular heart disease","heavy alcohol use","cardiotoxic chemotherapy"]},"pathophysiology":"The heart cannot pump enough blood at normal filling pressures. In heart failure with reduced ejection fraction (HFrEF) the ventricle dilates and contracts poorly; in heart failure with preserved ejection fraction (HFpEF) it is stiff and fills poorly. Activation of the renin-angiotensin-aldosterone system and the sympathetic nervous system drives sodium retention and remodeling.","timeline":{"onset":"Gradual, over months to years","course":"Progressive, with acute decompensations; guideline-directed therapy lowers mortality in HFrEF"},"key_findings":{"history":["exertional dyspnea","orthopnea","paroxysmal nocturnal dyspnea","ankle swelling","fatigue"],"exam":["raised jugular venous pressure","S3 gallop","bibasilar crackles","pitting edema","displaced apex beat"],"labs":["raised BNP or NT-proBNP","hyponatremia in advanced disease"],"imaging":["echocardiogram showing the ejection fraction and wall motion","chest X-ray with cardiomegaly, upper lobe venous diversion and Kerley B lines"]},"diagnosis":{"confirmatory_tests":["echocardiogram","BNP or NT-proBNP"],"criteria":["HFrEF: ejection fraction 40% or less","HFmrEF: ejection fraction 41 to 49%","HFpEF: ejection fraction 50% or more"]},"management":{"first_line":["HFrEF: four drug classes, an ARNI (sacubitril-valsartan) or ACE inhibitor or ARB, an evidence-based beta blocker, a mineralocorticoid receptor antagonist and an SGLT2 inhibitor","loop diuretics for congestion","exercise, vaccination and avoiding excess salt"],"next_line":["ICD for an ejection fraction of 35% or less despite three months of therapy","cardiac resynchronization therapy for an ejection fraction of 35% or less with left bundle branch block and a wide QRS","hydralazine with isosorbide dinitrate, especially for Black patients","LVAD or heart transplant in advanced disease"]},"complications":["acute decompensation","ventricular arrhythmias and sudden death","atrial fibrillation","cardiorenal syndrome","thromboembolism"]}'::jsonb),
  ('hyperkalemia', 1, 'in_review', null, null, '{"kind":"disease","name":"Hyperkalemia","aliases":["high potassium"],"systems":["renal"],"rotation":["IM","EM"],"confused_with":[],"pearls":["Calcium protects the heart within minutes but does not lower potassium; you still need to shift and remove it."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1495911001468"},{"kind":"note","id":"1496783778319"},{"kind":"note","id":"1496795383464"},{"kind":"note","id":"1535225879303"},{"kind":"note","id":"1555494970633"}],"sources":[{"title":"Clinical Practice Guidelines: Treatment of Acute Hyperkalaemia in Adults (UK Kidney Association, 2023)"}],"epidemiology":{"who":"People with kidney disease or diabetes, or on drugs that raise potassium","risk_factors":["acute kidney injury","chronic kidney disease","ACE inhibitors or ARBs","potassium-sparing diuretics","rhabdomyolysis","adrenal insufficiency"]},"pathophysiology":"Reduced potassium excretion or a shift out of cells raises serum potassium, which depolarizes heart and muscle cells and slows cardiac conduction.","timeline":{"onset":"Acute or chronic","course":"Can cause fatal arrhythmias once ECG changes appear"},"key_findings":{"history":["often no symptoms","muscle weakness","palpitations"],"exam":["weakness","bradycardia"],"labs":["serum potassium above 5.5 mEq/L","pseudohyperkalemia from a hemolyzed sample","ECG: peaked T waves, then PR prolongation and a wide QRS, progressing to a sine wave"],"imaging":[]},"diagnosis":{"confirmatory_tests":["repeat serum potassium","12-lead ECG"],"criteria":["serum potassium above 5.5 mEq/L; severe at 6.5 mEq/L or above, or with ECG changes"]},"management":{"first_line":["IV calcium gluconate to stabilize the heart","insulin with glucose to shift potassium into cells","beta-2 agonist such as nebulized albuterol"],"next_line":["remove potassium: loop diuretics, potassium binders or dialysis","stop potassium-raising drugs"]},"complications":["ventricular fibrillation","asystole","bradyarrhythmias"]}'::jsonb),
  ('hyperosmolar-hyperglycemic-state', 1, 'in_review', null, null, '{"kind":"disease","name":"Hyperosmolar hyperglycemic state","aliases":["HHS"],"systems":["endo"],"rotation":["IM","EM"],"confused_with":[{"script_id":"diabetic-ketoacidosis","how_to_tell_apart":"DKA has ketones and an anion gap acidosis and develops over hours; HHS has much higher glucose and osmolality, little or no ketosis, and develops over days.","compare":[{"label":"Glucose","text":"Usually over 600 mg/dL","source_field":"key_findings.labs[0]"},{"label":"Acidosis","text":"pH 7.3 or higher","source_field":"key_findings.labs[2]"},{"label":"Ketones","text":"Little or none","source_field":"key_findings.labs[3]"}]}],"pearls":["In HHS, fluids come first: insulin before adequate fluid replacement shifts water into cells and can worsen hypotension."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1502845294644"},{"kind":"note","id":"1502846424371"},{"kind":"note","id":"1550626495694"},{"kind":"note","id":"1555720980431"},{"kind":"note","id":"1585334906873"}],"sources":[{"title":"Hyperglycemic Crises in Adults With Diabetes: A Consensus Report (Diabetes Care, 2024)"}],"epidemiology":{"who":"Older adults with type 2 diabetes, often with limited access to water","risk_factors":["infection","insufficient insulin or missed medications","myocardial infarction","stroke","glucocorticoids","thiazide diuretics"]},"pathophysiology":"Relative insulin deficiency, with enough insulin to prevent ketogenesis, causes severe hyperglycemia, an osmotic diuresis, profound dehydration and hyperosmolality.","timeline":{"onset":"Develops over days to weeks","course":"Slower to correct than DKA, with a higher mortality"},"key_findings":{"history":["polyuria and polydipsia over days to weeks","weakness","confusion or drowsiness"],"exam":["severe dehydration","altered mental status, from lethargy to coma","focal neurologic signs or seizures in some"],"labs":["glucose usually above 600 mg/dL","effective serum osmolality above 300 mOsm/kg","pH 7.3 or higher and bicarbonate 15 mEq/L or higher","little or no ketonemia"],"imaging":[]},"diagnosis":{"confirmatory_tests":["serum glucose","calculated effective serum osmolality","serum beta-hydroxybutyrate to exclude significant ketosis"],"criteria":["glucose of 600 mg/dL or more","effective serum osmolality above 300 mOsm/kg (or total above 320)","pH 7.3 or higher, bicarbonate 15 mEq/L or higher, and no significant ketonemia"]},"management":{"first_line":["aggressive IV isotonic fluids","IV insulin infusion once fluids are running and potassium is at least 3.5 mEq/L","potassium replacement"],"next_line":["lower glucose, sodium and osmolality gradually to avoid cerebral edema","treat the precipitant","VTE prophylaxis"]},"complications":["cerebral edema from overly rapid correction","venous thromboembolism","rhabdomyolysis","acute kidney injury"]}'::jsonb),
  ('hyperthyroidism', 1, 'in_review', null, null, '{"kind":"disease","name":"Hyperthyroidism","aliases":["thyrotoxicosis","Graves disease"],"systems":["endo"],"rotation":["IM","FM"],"confused_with":[],"pearls":["Methimazole and propylthiouracil can cause agranulocytosis: stop the drug and check a white count if fever or a sore throat develops."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1502847845332"},{"kind":"note","id":"1547916081745"},{"kind":"note","id":"1548274605064"},{"kind":"note","id":"1557341643876"},{"kind":"note","id":"1580516060026"},{"kind":"note","id":"1552147637583","rung":"recall"},{"kind":"note","id":"1552158235283","rung":"recall"},{"kind":"note","id":"1585078817088","rung":"recall"},{"kind":"note","id":"1493675300258","rung":"management"},{"kind":"note","id":"1502563194507","rung":"management"},{"kind":"note","id":"1502929712391","rung":"management"}],"sources":[{"title":"2016 American Thyroid Association Guidelines for Diagnosis and Management of Hyperthyroidism and Other Causes of Thyrotoxicosis"}],"epidemiology":{"who":"Most often young to middle-aged women with Graves disease","risk_factors":["Graves disease","toxic multinodular goiter","toxic adenoma","thyroiditis","excess thyroid hormone intake","amiodarone"]},"pathophysiology":"Excess thyroid hormone, most often from TSH-receptor antibodies stimulating the gland in Graves disease, speeds metabolism and sympathetic activity.","timeline":{"onset":"Weeks to months","course":"Graves disease may remit after 12 to 18 months of antithyroid drugs"},"key_findings":{"history":["weight loss despite a good appetite","heat intolerance","palpitations","anxiety and tremor","frequent stools"],"exam":["tachycardia or atrial fibrillation","fine tremor","goiter","exophthalmos and pretibial myxedema in Graves disease"],"labs":["low TSH","high free T4 or T3","TSH-receptor antibodies in Graves disease"],"imaging":["radioactive iodine uptake scan: diffuse high uptake in Graves disease, low uptake in thyroiditis"]},"diagnosis":{"confirmatory_tests":["TSH","free T4","TSH-receptor antibodies or a radioactive iodine uptake scan to find the cause"],"criteria":["suppressed TSH with raised free T4 or T3"]},"management":{"first_line":["beta-blocker such as propranolol for symptoms","methimazole"],"next_line":["propylthiouracil in the first trimester of pregnancy and in thyroid storm","radioactive iodine ablation","thyroidectomy"]},"complications":["atrial fibrillation","thyroid storm","osteoporosis","agranulocytosis from antithyroid drugs"]}'::jsonb),
  ('hypertrophic-cardiomyopathy', 1, 'in_review', null, null, '{"kind":"disease","name":"Hypertrophic cardiomyopathy","aliases":["HCM","hypertrophic obstructive cardiomyopathy","HOCM"],"systems":["cardio"],"rotation":["IM"],"confused_with":[{"script_id":"aortic-stenosis","how_to_tell_apart":"Hypertrophic cardiomyopathy causes a systolic murmur at the left lower sternal border that gets louder with Valsalva or standing; the murmur of aortic stenosis radiates to the carotids and gets softer. Hypertrophic cardiomyopathy is inherited and shows up in the young; aortic stenosis is a disease of older adults.","compare":[{"label":"Murmur","text":"Left lower sternal border","source_field":"key_findings.exam[0]"},{"label":"Valsalva","text":"Louder","source_field":"key_findings.exam[0]"},{"label":"Who","text":"Young, inherited","source_field":"epidemiology.who"}]}],"pearls":["Anything that shrinks the ventricle (Valsalva, standing, dehydration) makes the obstruction and murmur worse; squatting and handgrip make them softer.","Hypertrophic cardiomyopathy is inherited in an autosomal dominant pattern.","Systolic anterior motion of the mitral valve also causes mitral regurgitation."],"difficulty_tiers":{"MS1-2":["pathophysiology","pearls[1]"],"MS3":["key_findings.exam[0]","management.first_line"],"MS4":["management.next_line"]},"anki_refs":[],"sources":[{"title":"2024 AHA/ACC/AMSSM/HRS/PACES/SCMR Guideline for the Management of Hypertrophic Cardiomyopathy"},{"title":"2023 ESC Guidelines for the management of cardiomyopathies"}],"epidemiology":{"who":"Any age, often first found in adolescents and young adults; the most common inherited heart disease (about 1 in 500) and a leading cause of sudden death in young athletes","risk_factors":["family history of hypertrophic cardiomyopathy or sudden death","a sarcomere gene variant, most often in beta-myosin heavy chain or myosin-binding protein C"]},"pathophysiology":"A variant in a sarcomere protein causes asymmetric hypertrophy of the left ventricle, usually of the septum, with disorganized myocytes (myocyte disarray). The stiff ventricle fills poorly. In the obstructive form, the anterior mitral leaflet is pulled toward the septum in systole (systolic anterior motion), obstructing outflow and causing mitral regurgitation.","timeline":{"onset":"Often appears in adolescence or early adulthood","course":"Variable: many live normal lives, but some develop sudden death, heart failure or atrial fibrillation"},"key_findings":{"history":["exertional dyspnea","chest pain","syncope or presyncope on exertion","palpitations","sudden death may be the first sign"],"exam":["systolic ejection murmur at the left lower sternal border that gets louder with Valsalva or standing and softer with squatting or handgrip","S4","bifid carotid pulse"],"labs":["genetic testing for sarcomere variants"],"imaging":["echocardiogram showing a septum 15 mm or thicker, often with systolic anterior motion of the mitral valve","cardiac MRI showing hypertrophy and fibrosis","ECG with left ventricular hypertrophy and deep Q waves"]},"diagnosis":{"confirmatory_tests":["echocardiogram","cardiac MRI"],"criteria":["Left ventricular wall thickness of 15 mm or more (13 mm or more with a family history), not explained by another cause"]},"management":{"first_line":["beta blocker for symptoms","avoid dehydration and vasodilators","ICD for patients at high risk of sudden death","screen first-degree relatives with ECG and echocardiogram"],"next_line":["verapamil or diltiazem if beta blockers fail","mavacamten, a cardiac myosin inhibitor, for obstructive symptoms","septal reduction: surgical myectomy or alcohol septal ablation"]},"complications":["sudden cardiac death from ventricular arrhythmia","atrial fibrillation","heart failure","mitral regurgitation"]}'::jsonb),
  ('hyponatremia', 1, 'in_review', null, null, '{"kind":"disease","name":"Hyponatremia","aliases":["low sodium"],"systems":["renal","endo"],"rotation":["IM"],"confused_with":[],"pearls":["Correcting chronic hyponatremia too fast causes osmotic demyelination syndrome; limit the rise to 8 mEq/L in 24 hours."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1496783896138"},{"kind":"note","id":"1497567515289"},{"kind":"note","id":"1535224314327"},{"kind":"note","id":"1550658787885"},{"kind":"note","id":"1555494262417"}],"sources":[{"title":"Clinical practice guideline on diagnosis and treatment of hyponatraemia (ESE, ERA-EDTA and ESICM, 2014)"}],"epidemiology":{"who":"Older adults, hospitalized patients, and people on thiazides or SSRIs","risk_factors":["thiazide diuretics","SIADH","heart failure","cirrhosis","SSRIs","excess water intake"]},"pathophysiology":"Too much water relative to sodium, usually from ADH-driven water retention. After confirming low serum osmolality, it is classified by volume status.","timeline":{"onset":"Acute (under 48 hours) or chronic","course":"Chronic hyponatremia must be corrected slowly"},"key_findings":{"history":["nausea","headache","confusion","falls"],"exam":["assess volume status: dry, euvolemic or edematous","seizures or reduced consciousness when severe"],"labs":["serum sodium below 135 mEq/L","low serum osmolality in true (hypotonic) hyponatremia","urine osmolality above 100 mOsm/kg and urine sodium above 30 mEq/L in SIADH"],"imaging":[]},"diagnosis":{"confirmatory_tests":["serum osmolality","urine osmolality","urine sodium","volume status assessment"],"criteria":["serum sodium below 135 mEq/L; severe below 120 mEq/L"]},"management":{"first_line":["hypertonic 3% saline bolus for severe symptoms such as seizures","fluid restriction for SIADH","isotonic saline for hypovolemic hyponatremia","stop the offending drug"],"next_line":["limit correction to 8 mEq/L in 24 hours in chronic hyponatremia","urea or vaptans for refractory SIADH","treat heart failure or cirrhosis in hypervolemic hyponatremia"]},"complications":["seizures","cerebral edema","osmotic demyelination syndrome from overly rapid correction","falls and fractures"]}'::jsonb),
  ('infective-endocarditis', 1, 'in_review', null, null, '{"kind":"disease","name":"Infective endocarditis","aliases":["endocarditis"],"systems":["cardio"],"rotation":["IM"],"confused_with":[],"pearls":["Endocarditis in people who inject drugs often affects the tricuspid valve and causes septic pulmonary emboli."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1497045640067"},{"kind":"note","id":"1550787795139"},{"kind":"note","id":"1551617026447"},{"kind":"note","id":"1579382616920"},{"kind":"note","id":"1579382907963"},{"kind":"note","id":"1504743646378","rung":"recall"},{"kind":"note","id":"1539379437968","rung":"recall"},{"kind":"note","id":"1553162828660","rung":"recall"},{"kind":"note","id":"1550694289942","rung":"management"},{"kind":"note","id":"1555458022589","rung":"management"},{"kind":"note","id":"1590016185294","rung":"management"}],"sources":[{"title":"2023 ESC Guidelines for the management of endocarditis"},{"title":"The 2023 Duke-International Society for Cardiovascular Infectious Diseases Criteria for Infective Endocarditis"}],"epidemiology":{"who":"People who inject drugs, and those with prosthetic valves, prior endocarditis or structural heart disease","risk_factors":["injection drug use","prosthetic heart valve","prior endocarditis","structural or congenital heart disease","indwelling intravascular devices","hemodialysis"]},"pathophysiology":"Bacteria, most often Staphylococcus aureus, seed a heart valve and form vegetations that destroy the valve and shed septic emboli.","timeline":{"onset":"Acute over days (S. aureus) or subacute over weeks (viridans streptococci)","course":"Fatal without treatment; many patients need surgery"},"key_findings":{"history":["fever","fatigue and weight loss in subacute disease","new heart failure symptoms"],"exam":["new regurgitant murmur","splinter hemorrhages","painless Janeway lesions on the palms and soles","painful Osler nodes on the fingers","Roth spots"],"labs":["persistently positive blood cultures","raised inflammatory markers","hematuria from glomerulonephritis"],"imaging":["echocardiogram showing a vegetation: transthoracic first, transesophageal if negative or with a prosthetic valve"]},"diagnosis":{"confirmatory_tests":["three sets of blood cultures before antibiotics","echocardiogram"],"criteria":["Duke criteria: typical organisms in blood cultures and evidence of endocardial involvement are the major criteria"]},"management":{"first_line":["empiric IV vancomycin after blood cultures","prolonged IV antibiotics (4 to 6 weeks) guided by culture results"],"next_line":["surgery for heart failure, uncontrolled infection, abscess, or large vegetations with embolism"]},"complications":["heart failure from valve destruction","septic emboli to the brain, lungs, spleen or kidneys","perivalvular abscess","glomerulonephritis"]}'::jsonb),
  ('iron-deficiency-anemia', 1, 'in_review', null, null, '{"kind":"disease","name":"Iron deficiency anemia","aliases":["IDA"],"systems":["heme_onc"],"rotation":["IM","FM","peds"],"confused_with":[],"pearls":["Iron deficiency in a man or a postmenopausal woman is GI cancer until proven otherwise: scope both ends."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1482959756657","rung":"recall"},{"kind":"note","id":"1482959769125","rung":"recall"},{"kind":"note","id":"1539943644042","rung":"recall"},{"kind":"note","id":"1495729518859","rung":"management"},{"kind":"note","id":"1554630354556","rung":"management"},{"kind":"note","id":"1578616580406","rung":"management"}],"sources":[{"title":"AGA Clinical Practice Guidelines on the Gastrointestinal Evaluation of Iron Deficiency Anemia (2020)"}],"epidemiology":{"who":"Menstruating and pregnant women, infants, and older adults with GI blood loss","risk_factors":["heavy menstrual bleeding","gastrointestinal blood loss","pregnancy","low dietary iron","celiac disease","bariatric surgery"]},"pathophysiology":"Blood loss or poor absorption depletes iron stores, limiting hemoglobin synthesis and producing small, pale red cells.","timeline":{"onset":"Weeks to months","course":"Hemoglobin rises about 1 to 2 g/dL over 2 to 3 weeks of replacement"},"key_findings":{"history":["fatigue","exertional dyspnea","pica, especially craving ice","restless legs"],"exam":["pallor","koilonychia (spoon nails)","angular cheilitis"],"labs":["microcytic anemia (low MCV)","low ferritin","high RDW","low transferrin saturation","high total iron-binding capacity"],"imaging":[]},"diagnosis":{"confirmatory_tests":["serum ferritin","complete blood count"],"criteria":["ferritin below 30 ng/mL confirms iron deficiency in most adults"]},"management":{"first_line":["oral iron, once daily or on alternate days","find and treat the cause of blood loss"],"next_line":["IV iron if oral iron fails or isn''t tolerated","colonoscopy and upper endoscopy in men and postmenopausal women"]},"complications":["heart failure from severe anemia","poor pregnancy outcomes"]}'::jsonb),
  ('lipoprotein-metabolism', 1, 'in_review', null, null, '{"kind":"pathway","name":"Lipoprotein metabolism","aliases":["lipid transport"],"systems":["cardio","general"],"rotation":[],"confused_with":[],"pearls":["Chylomicrons carry apoB-48; VLDL, IDL and LDL carry apoB-100.","Triglycerides above 1000 mg/dL make the plasma milky and raise the risk of acute pancreatitis.","Tendon xanthomas, especially of the Achilles tendon, suggest familial hypercholesterolemia."],"difficulty_tiers":{"MS1-2":["steps","regulation","deficiencies"],"MS3":["drug_targets","pearls[1]"],"MS4":["treatment","deficiencies[3]"]},"anki_refs":[],"sources":[{"title":"Lippincott Illustrated Reviews: Biochemistry"},{"title":"Harper''s Illustrated Biochemistry"},{"title":"2018 AHA/ACC Guideline on the Management of Blood Cholesterol"}],"location":"Intestine, blood and liver","purpose":"Carries triglycerides and cholesterol, which do not dissolve in water, through the blood in lipoproteins: from the gut (the exogenous pathway), from the liver (the endogenous pathway) and back to the liver (reverse cholesterol transport).","steps":["the intestine packages dietary fat into chylomicrons, which carry apoB-48","lipoprotein lipase in capillaries releases fatty acids from chylomicrons and VLDL","the liver takes up chylomicron remnants through apoE","the liver secretes VLDL, which carries apoB-100 and becomes IDL and then LDL","LDL delivers cholesterol to tissues through LDL receptors, which bind apoB-100","HDL collects cholesterol from tissues and returns it to the liver (reverse cholesterol transport)"],"regulation":["insulin activates lipoprotein lipase","apoC-II activates lipoprotein lipase","LCAT, activated by apoA-I, esterifies cholesterol in HDL","cholesteryl ester transfer protein (CETP) moves cholesteryl esters from HDL to VLDL and LDL"],"cofactors":["apoC-II for lipoprotein lipase","apoE for remnant uptake","apoB-100 for binding the LDL receptor"],"deficiencies":["familial chylomicronemia (type I): lipoprotein lipase or apoC-II deficiency, with very high triglycerides, pancreatitis and eruptive xanthomas","familial hypercholesterolemia (type IIa): a defective LDL receptor, with very high LDL, tendon xanthomas and early heart attacks","dysbetalipoproteinemia (type III): apoE2 variant, with palmar xanthomas","abetalipoproteinemia: MTP deficiency, with no apoB lipoproteins, fat malabsorption, acanthocytes and vitamin E deficiency"],"drug_targets":["statins raise the number of LDL receptors","PCSK9 inhibitors stop LDL receptors from being broken down","fibrates activate PPAR-alpha and lipoprotein lipase, lowering triglycerides","ezetimibe blocks cholesterol absorption in the intestine"],"treatment":["familial hypercholesterolemia: high-intensity statin, then ezetimibe and PCSK9 inhibitors","familial chylomicronemia: a very low-fat diet","abetalipoproteinemia: fat-soluble vitamins, especially vitamin E, and a low-fat diet"]}'::jsonb),
  ('loop-diuretics', 1, 'in_review', null, null, '{"kind":"drug","name":"Loop diuretics","aliases":["loop diuretic"],"systems":["cardio","renal"],"rotation":[],"confused_with":[],"pearls":["Loops lose calcium, thiazides keep it: loop diuretics cause hypocalcemia, thiazides cause hypercalcemia.","Ethacrynic acid is the loop diuretic without a sulfonamide group, used when a sulfa reaction is a concern.","Loop diuretics cause a hypokalemic metabolic alkalosis, also called contraction alkalosis."],"difficulty_tiers":{"MS1-2":["mechanism","adverse_effects"],"MS3":["indications","monitoring"],"MS4":["pharmacokinetics[1]","pearls[1]"]},"anki_refs":[],"sources":[{"title":"Katzung''s Basic and Clinical Pharmacology"},{"title":"Goodman & Gilman''s The Pharmacological Basis of Therapeutics"},{"title":"2022 AHA/ACC/HFSA Guideline for the Management of Heart Failure"}],"class":"Loop diuretics","class_members":["furosemide","bumetanide","torsemide","ethacrynic acid"],"mechanism":"Block the Na-K-2Cl cotransporter (NKCC2) in the thick ascending limb of the loop of Henle. Sodium and water loss is strong, and more calcium and magnesium are lost in the urine.","pharmacokinetics":["work within minutes when given IV","oral furosemide is absorbed variably; bumetanide and torsemide are absorbed more reliably","all are sulfonamides except ethacrynic acid"],"indications":["fluid overload in heart failure","acute pulmonary edema","edema from cirrhosis or nephrotic syndrome","hyperkalemia"],"adverse_effects":["hypokalemia","hypomagnesemia","hypocalcemia","volume depletion and prerenal kidney injury","ototoxicity","metabolic alkalosis","hyperuricemia and gout"],"contraindications":["anuria","severe volume depletion"],"interactions":["aminoglycosides add to ototoxicity","raise lithium levels","digoxin toxicity is more likely with low potassium or magnesium"],"monitoring":["potassium, magnesium and creatinine","daily weight and fluid balance"],"overdose":{"features":["dehydration","hypotension","electrolyte loss"],"treatment":["IV fluids and electrolyte replacement"]}}'::jsonb),
  ('nephritic-syndrome', 1, 'in_review', null, null, '{"kind":"disease","name":"Nephritic syndrome","aliases":["acute glomerulonephritis"],"systems":["renal"],"rotation":["IM","peds"],"confused_with":[{"script_id":"nephrotic-syndrome","how_to_tell_apart":"Nephrotic syndrome has heavy proteinuria above 3.5 g/day, low albumin and a bland urine sediment; nephritic syndrome has red blood cell casts, hypertension and a rising creatinine.","compare":[{"label":"Urine","text":"Hematuria, RBC casts","source_field":"key_findings.labs[0]"},{"label":"Protein","text":"Under 3.5 g/day","source_field":"key_findings.labs[2]"},{"label":"Classic","text":"Post-strep GN","source_field":"epidemiology.risk_factors[0]"}]}],"pearls":["IgA nephropathy causes hematuria within a few days of an upper respiratory infection, while post-streptococcal glomerulonephritis appears 1 to 3 weeks after a sore throat."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["key_findings.labs[0]","epidemiology.risk_factors","management.first_line"],"MS4":["pearls[0]","management.next_line[1]"]},"anki_refs":[{"kind":"note","id":"1471806675606"},{"kind":"note","id":"1471806688179"},{"kind":"note","id":"1475376633607"},{"kind":"note","id":"1555536173966"},{"kind":"note","id":"1582854828887"}],"sources":[{"title":"KDIGO 2021 Clinical Practice Guideline for the Management of Glomerular Diseases"}],"epidemiology":{"who":"Children and adults; post-infectious glomerulonephritis is common in children, and IgA nephropathy is the most common glomerulonephritis worldwide","risk_factors":["post-streptococcal glomerulonephritis","IgA nephropathy","lupus nephritis","ANCA-associated vasculitis","anti-GBM disease","infective endocarditis"]},"pathophysiology":"Immune-mediated inflammation of the glomeruli damages the capillary walls, letting red cells into the urine and lowering filtration, which causes salt and water retention, hypertension and a rising creatinine.","timeline":{"onset":"Days to weeks","course":"Post-streptococcal disease usually resolves in children; rapidly progressive forms can cause kidney failure within weeks"},"key_findings":{"history":["cola-colored urine","reduced urine output","recent sore throat or skin infection"],"exam":["hypertension","periorbital or leg edema"],"labs":["hematuria with red blood cell casts and dysmorphic red cells","rising creatinine","proteinuria usually below 3.5 g/day","low complement C3 in post-streptococcal glomerulonephritis and lupus nephritis"],"imaging":[]},"diagnosis":{"confirmatory_tests":["urinalysis with microscopy for red blood cell casts","complement levels (C3 and C4)","serologies: ANCA, anti-GBM, ANA, ASO","kidney biopsy"],"criteria":["hematuria with red cell casts, hypertension, edema and reduced kidney function"]},"management":{"first_line":["supportive care","blood pressure control","loop diuretics and salt restriction for fluid overload","treat the underlying cause"],"next_line":["immunosuppression (steroids with cyclophosphamide or rituximab) for rapidly progressive disease such as ANCA vasculitis","plasma exchange for anti-GBM disease","dialysis for refractory fluid overload, hyperkalemia or uremia"]},"complications":["acute kidney injury","hypertensive emergency","pulmonary edema","progression to chronic kidney disease"]}'::jsonb),
  ('nephrotic-syndrome', 1, 'in_review', null, null, '{"kind":"disease","name":"Nephrotic syndrome","aliases":[],"systems":["renal"],"rotation":["IM","peds"],"confused_with":[{"script_id":"nephritic-syndrome","how_to_tell_apart":"Nephritic syndrome has hematuria with red blood cell casts, hypertension and a rising creatinine, with proteinuria usually below 3.5 g/day; nephrotic syndrome has heavy proteinuria above 3.5 g/day with a bland sediment.","compare":[{"label":"Urine","text":"Fatty casts","source_field":"key_findings.labs[3]"},{"label":"Protein","text":"Over 3.5 g/day","source_field":"key_findings.labs[0]"},{"label":"Classic","text":"Minimal change","source_field":"epidemiology.who"}]}],"pearls":["Urinary loss of antithrombin III makes nephrotic patients hypercoagulable; renal vein thrombosis is classic with membranous nephropathy."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.criteria[0]","epidemiology.risk_factors","management.first_line[0]"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1475363774930"},{"kind":"note","id":"1475364023607"},{"kind":"note","id":"1497562168496"},{"kind":"note","id":"1539282631413"},{"kind":"note","id":"1555542582278"}],"sources":[{"title":"KDIGO 2021 Clinical Practice Guideline for the Management of Glomerular Diseases"}],"epidemiology":{"who":"Children, usually from minimal change disease, and adults, most often from membranous nephropathy, FSGS or diabetic kidney disease","risk_factors":["minimal change disease","focal segmental glomerulosclerosis","membranous nephropathy","diabetic nephropathy","amyloidosis","lupus nephritis"]},"pathophysiology":"Injury to the glomerular filtration barrier (the podocytes) lets large amounts of protein leak into the urine, causing low serum albumin, edema and a compensatory rise in hepatic lipoprotein synthesis. Urinary loss of anticoagulant proteins makes patients hypercoagulable.","timeline":{"onset":"Usually over weeks","course":"Minimal change disease often remits with steroids; other causes may progress to chronic kidney disease"},"key_findings":{"history":["swelling around the eyes and legs","foamy urine","weight gain"],"exam":["pitting edema","periorbital edema","ascites or pleural effusions"],"labs":["proteinuria above 3.5 g/day","serum albumin below 3 g/dL","hyperlipidemia","fatty casts and oval fat bodies in the urine"],"imaging":[]},"diagnosis":{"confirmatory_tests":["urine protein-to-creatinine ratio","24-hour urine protein","kidney biopsy to find the cause in adults"],"criteria":["proteinuria above 3.5 g/day with hypoalbuminemia and edema; hyperlipidemia is common"]},"management":{"first_line":["ACE inhibitor or ARB to reduce proteinuria","loop diuretics and salt restriction for edema","treat the underlying cause"],"next_line":["corticosteroids for minimal change disease","statin for persistent hyperlipidemia","anticoagulation for thrombosis"]},"complications":["renal vein thrombosis","deep vein thrombosis and pulmonary embolism","infection","acute kidney injury"]}'::jsonb),
  ('nitrates', 1, 'in_review', null, null, '{"kind":"drug","name":"Nitrates","aliases":["organic nitrates"],"systems":["cardio"],"rotation":[],"confused_with":[],"pearls":["A nitrate-free interval of 10 to 12 hours each day prevents tolerance.","Workers exposed to nitrates in explosives factories get headaches and dizziness at the start of the week that fade by the weekend (Monday disease).","Avoid nitrates in right ventricular infarction (low blood pressure, raised JVP, clear lungs), which depends on preload."],"difficulty_tiers":{"MS1-2":["mechanism","adverse_effects"],"MS3":["indications","contraindications"],"MS4":["overdose","pearls[1]"]},"anki_refs":[],"sources":[{"title":"Katzung''s Basic and Clinical Pharmacology"},{"title":"Goodman & Gilman''s The Pharmacological Basis of Therapeutics"},{"title":"2023 AHA/ACC/ACCP/ASPC/NLA/PCNA Guideline for the Management of Patients With Chronic Coronary Disease"}],"class":"Organic nitrates (nitric oxide donors)","class_members":["nitroglycerin","isosorbide dinitrate","isosorbide mononitrate"],"mechanism":"Release nitric oxide in vascular smooth muscle, which raises cGMP and relaxes the vessel. Veins dilate much more than arteries, so preload and ventricular wall stress fall and the heart needs less oxygen.","pharmacokinetics":["nitroglycerin has high first-pass metabolism, so it is given sublingually, as a patch or IV","isosorbide mononitrate is taken by mouth once daily"],"indications":["relief of an angina attack (sublingual nitroglycerin)","angina prevention (long-acting nitrates)","chest pain in acute coronary syndrome","acute pulmonary edema","hypertensive emergency (IV nitroglycerin)","heart failure, as isosorbide dinitrate with hydralazine"],"adverse_effects":["headache","flushing","hypotension","reflex tachycardia","tolerance with continuous use"],"contraindications":["use of a PDE5 inhibitor: sildenafil in the past 24 hours or tadalafil in the past 48 hours","right ventricular infarction","severe aortic stenosis","hypertrophic obstructive cardiomyopathy"],"interactions":["PDE5 inhibitors cause severe hypotension"],"monitoring":["blood pressure"],"overdose":{"features":["hypotension","methemoglobinemia"],"treatment":["methylene blue for methemoglobinemia"]}}'::jsonb),
  ('pulmonary-embolism', 1, 'in_review', null, null, '{"kind":"disease","name":"Pulmonary embolism","aliases":["PE"],"systems":["pulm","heme_onc"],"rotation":["IM","EM","surgery"],"confused_with":[{"script_id":"community-acquired-pneumonia","how_to_tell_apart":"Pneumonia usually brings fever, productive cough, focal crackles and a consolidation on chest X-ray; PE more often has clear lungs and a near-normal X-ray despite hypoxemia.","compare":[{"label":"Lungs","text":"Clear","source_field":"key_findings.exam[3]"},{"label":"Imaging","text":"Filling defect on CTPA","source_field":"key_findings.imaging[0]"},{"label":"Treat","text":"Anticoagulation","source_field":"management.first_line[0]"}]},{"script_id":"deep-vein-thrombosis","how_to_tell_apart":"DVT is the usual source of PE: look for unilateral leg swelling and calf pain, and confirm with compression ultrasound.","compare":[{"label":"Symptom","text":"Sudden dyspnea","source_field":"key_findings.history[0]"},{"label":"Test","text":"CT pulmonary angiogram","source_field":"diagnosis.confirmatory_tests[0]"},{"label":"Treat","text":"DOAC","source_field":"management.first_line[0]"}]},{"script_id":"acute-coronary-syndrome","how_to_tell_apart":"Acute coronary syndrome causes pressure-like chest pain with ST changes on the ECG and a rise and fall of troponin; pulmonary embolism causes sudden dyspnea, pleuritic pain and hypoxemia.","compare":[{"label":"Pain","text":"Pleuritic","source_field":"key_findings.history[1]"},{"label":"First test","text":"CT pulmonary angiogram","source_field":"diagnosis.confirmatory_tests[0]"},{"label":"First drug","text":"Anticoagulation","source_field":"management.first_line[0]"}]}],"pearls":["The most common ECG finding in PE is sinus tachycardia; the classic S1Q3T3 pattern is uncommon."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["epidemiology.risk_factors","diagnosis.confirmatory_tests[0]","management.first_line[0]"],"MS4":["pearls[0]","management.next_line[0]","diagnosis.criteria[1]"]},"anki_refs":[{"kind":"note","id":"1495883335732","rung":"recall"},{"kind":"note","id":"1495883587351","rung":"recall"},{"kind":"note","id":"1550710294654","rung":"recall"},{"kind":"note","id":"1474426264636","rung":"management"},{"kind":"note","id":"1550710228646","rung":"management"},{"kind":"note","id":"1557155284271","rung":"management"}],"sources":[{"title":"2019 ESC Guidelines for the diagnosis and management of acute pulmonary embolism"},{"title":"Antithrombotic Therapy for VTE Disease: Second Update of the CHEST Guideline and Expert Panel Report (2021)"}],"epidemiology":{"who":"Adults with risk factors for venous thromboembolism","risk_factors":["recent surgery","immobilization","active cancer","prior VTE","estrogen use or pregnancy","inherited thrombophilia"]},"pathophysiology":"A thrombus, usually from the deep veins of the legs, lodges in the pulmonary arteries, causing ventilation-perfusion mismatch and hypoxemia; a large clot strains the right ventricle and can cause shock.","timeline":{"onset":"Sudden","course":"Most stable patients recover with anticoagulation; massive PE can cause sudden death"},"key_findings":{"history":["sudden dyspnea","pleuritic chest pain","hemoptysis","unilateral leg swelling"],"exam":["tachycardia","tachypnea","hypoxemia","clear lungs"],"labs":["raised D-dimer","raised troponin or BNP with right ventricular strain"],"imaging":["CT pulmonary angiography showing a filling defect","echocardiogram may show right ventricular dilation"]},"diagnosis":{"confirmatory_tests":["CT pulmonary angiography","V/Q scan if CT contrast is contraindicated"],"criteria":["use the Wells score to estimate pretest probability","with low pretest probability, a negative D-dimer rules out PE"]},"management":{"first_line":["anticoagulation, preferably a direct oral anticoagulant such as apixaban or rivaroxaban"],"next_line":["systemic thrombolysis for high-risk PE with hypotension","catheter-directed therapy or surgical embolectomy if thrombolysis fails or is contraindicated","IVC filter only if anticoagulation is contraindicated"]},"complications":["right heart failure","obstructive shock","pulmonary infarction","chronic thromboembolic pulmonary hypertension"]}'::jsonb),
  ('septic-shock', 1, 'in_review', null, null, '{"kind":"disease","name":"Sepsis and septic shock","aliases":["sepsis","septic shock"],"systems":["general"],"rotation":["IM","EM"],"confused_with":[{"script_id":"adrenal-insufficiency","how_to_tell_apart":"Adrenal crisis also causes shock that doesn''t respond to fluids, often with hyponatremia, hyperkalemia and hypoglycemia; suspect it in anyone on long-term steroids.","compare":[{"label":"Key lab","text":"Lactate over 2 mmol/L","source_field":"key_findings.labs[0]"},{"label":"Clue","text":"Fever or chills","source_field":"key_findings.history[0]"},{"label":"Treat","text":"Antibiotics within 1 hour","source_field":"management.first_line[0]"}]}],"pearls":["Target a mean arterial pressure of at least 65 mmHg; norepinephrine is the first-line vasopressor."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1494892379716"},{"kind":"note","id":"1530550150741"},{"kind":"note","id":"1536437425019"},{"kind":"note","id":"1539537920733"},{"kind":"note","id":"1557739493988"}],"sources":[{"title":"Surviving Sepsis Campaign: International Guidelines for Management of Sepsis and Septic Shock 2021"},{"title":"The Third International Consensus Definitions for Sepsis and Septic Shock (Sepsis-3, 2016)"}],"epidemiology":{"who":"Anyone with an infection; highest risk in older adults and the immunocompromised","risk_factors":["pneumonia","urinary tract infection","intra-abdominal infection","skin and soft tissue infection","indwelling lines or catheters"]},"pathophysiology":"A dysregulated host response to infection causes vasodilation, capillary leak and organ dysfunction.","timeline":{"onset":"Hours","course":"Mortality rises with each hour of delayed antibiotics in septic shock"},"key_findings":{"history":["fever or chills","confusion","symptoms of the source infection"],"exam":["hypotension","tachycardia","tachypnea","altered mental status","warm or mottled skin"],"labs":["lactate above 2 mmol/L","signs of organ dysfunction: rising creatinine or bilirubin, low platelets"],"imaging":["imaging to find the source, guided by symptoms"]},"diagnosis":{"confirmatory_tests":["blood cultures before antibiotics","serum lactate","SOFA score for organ dysfunction"],"criteria":["sepsis: suspected infection with an acute rise of 2 or more SOFA points","septic shock: vasopressors needed to keep MAP at 65 mmHg or more, with lactate above 2 mmol/L despite fluids"]},"management":{"first_line":["broad-spectrum antibiotics within 1 hour","30 mL/kg IV crystalloid for hypotension or lactate of 4 mmol/L or more","norepinephrine if hypotension persists"],"next_line":["source control","add vasopressin for rising norepinephrine needs","hydrocortisone for refractory shock"]},"complications":["multi-organ failure","ARDS","acute kidney injury","disseminated intravascular coagulation","death"]}'::jsonb),
  ('stable-angina', 1, 'in_review', null, null, '{"kind":"disease","name":"Stable angina","aliases":["chronic stable angina","angina pectoris"],"systems":["cardio"],"rotation":["IM"],"confused_with":[{"script_id":"acute-coronary-syndrome","how_to_tell_apart":"Stable angina comes on with exertion, settles with rest and leaves troponin normal; acute coronary syndrome brings pain at rest or a new crescendo pattern, and a myocardial infarction raises troponin."}],"pearls":["Beta blockers can worsen vasospastic (Prinzmetal) angina; calcium channel blockers treat it.","Nitrates are contraindicated within 24 hours of sildenafil or 48 hours of tadalafil, because the combination causes severe hypotension.","Nitrates relieve angina mainly by venodilation, which lowers preload and wall stress."],"difficulty_tiers":{"MS1-2":["pathophysiology","pearls[2]"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["management.next_line","pearls[0]"]},"anki_refs":[],"sources":[{"title":"2023 AHA/ACC/ACCP/ASPC/NLA/PCNA Guideline for the Management of Patients With Chronic Coronary Disease"},{"title":"2024 ESC Guidelines for the management of chronic coronary syndromes"}],"epidemiology":{"who":"Middle-aged and older adults with atherosclerotic coronary disease","risk_factors":["smoking","hypertension","diabetes","high LDL cholesterol","family history of premature coronary disease","older age","male sex"]},"pathophysiology":"A fixed atherosclerotic plaque narrows a coronary artery, usually by 70% or more, so blood flow cannot rise to meet the heart''s oxygen demand during exertion. The ischemia is brief and reverses with rest, without myocardial necrosis.","timeline":{"onset":"Predictable chest pain with exertion, building over months","course":"A stable pattern; pain at rest or a crescendo pattern means unstable angina"},"key_findings":{"history":["substernal chest pressure brought on by exertion or emotion","pain relieved by rest or nitroglycerin within minutes","radiation to the arm, neck or jaw","dyspnea on exertion"],"exam":["often normal between episodes","signs of atherosclerosis such as carotid bruits or xanthelasma"],"labs":["normal troponin","lipid panel and HbA1c to assess risk"],"imaging":["resting ECG often normal","exercise ECG showing ST depression","stress echocardiography or nuclear perfusion imaging showing ischemia","coronary CT angiography showing plaque"]},"diagnosis":{"confirmatory_tests":["stress testing: exercise ECG, stress echocardiography or myocardial perfusion imaging","coronary CT angiography","invasive coronary angiography when risk is high or symptoms persist"],"criteria":["Typical angina has three features: substernal discomfort, brought on by exertion or emotional stress, and relieved by rest or nitroglycerin"]},"management":{"first_line":["sublingual nitroglycerin for attacks","beta blocker or calcium channel blocker for symptom control","aspirin","high-intensity statin","risk factor control: stop smoking, treat blood pressure and diabetes"],"next_line":["long-acting nitrates or ranolazine added for persistent angina","revascularization with PCI or CABG for symptoms despite medical therapy or for high-risk anatomy such as left main disease"]},"complications":["acute coronary syndrome","heart failure","arrhythmias"]}'::jsonb),
  ('staphylococcus-aureus', 1, 'in_review', null, null, '{"kind":"bug","name":"Staphylococcus aureus","aliases":["S. aureus","Staph aureus"],"systems":["cardio","derm","msk"],"rotation":[],"confused_with":[{"script_id":"viridans-streptococci","how_to_tell_apart":"S. aureus grows in clusters, is catalase- and coagulase-positive and causes acute endocarditis over days; viridans streptococci grow in chains, are catalase-negative and cause subacute endocarditis over weeks.","compare":[{"label":"Gram stain","text":"Cocci in clusters","source_field":"morphology"},{"label":"Course","text":"Acute endocarditis","source_field":"diseases[1]"},{"label":"Key test","text":"Coagulase-positive","source_field":"lab_features[1]"}]},{"script_id":"enterococcus","how_to_tell_apart":"S. aureus grows in clusters and is catalase-positive; enterococci grow in pairs and short chains, are catalase-negative and grow in 6.5% salt.","compare":[{"label":"Gram stain","text":"Cocci in clusters","source_field":"morphology"},{"label":"Course","text":"Acute endocarditis","source_field":"diseases[1]"},{"label":"Key test","text":"Coagulase-positive","source_field":"lab_features[1]"}]}],"pearls":["MRSA resists beta-lactams because the mecA gene encodes an altered penicillin-binding protein (PBP2a).","Daptomycin is inactivated by lung surfactant, so it cannot treat pneumonia.","S. aureus in a blood culture should never be dismissed as a contaminant: repeat blood cultures and get an echocardiogram."],"difficulty_tiers":{"MS1-2":["morphology","lab_features","virulence_factors"],"MS3":["diseases","treatment"],"MS4":["pearls[1]","pearls[2]"]},"anki_refs":[],"sources":[{"title":"Sherris & Ryan''s Medical Microbiology"},{"title":"2023 ESC Guidelines for the management of endocarditis"},{"title":"Clinical Practice Guidelines by the Infectious Diseases Society of America for the Treatment of Methicillin-Resistant Staphylococcus aureus Infections in Adults and Children"}],"morphology":"Gram-positive cocci in clusters","lab_features":["catalase-positive","coagulase-positive","beta-hemolytic","golden-yellow colonies","ferments mannitol on mannitol salt agar"],"transmission":["colonizes the anterior nares of about 30% of people","spreads by direct contact and on hands","enters through broken skin, catheters and injection drug use"],"virulence_factors":["protein A, which binds the Fc region of IgG and blocks opsonization","coagulase, which coats the bacteria in fibrin","Panton-Valentine leukocidin, which kills white cells, in community MRSA","toxic shock syndrome toxin (TSST-1), a superantigen","exfoliative toxins, which cause scalded skin syndrome","preformed enterotoxins, which cause food poisoning"],"diseases":["skin and soft tissue infections: abscesses, furuncles, cellulitis and impetigo","acute endocarditis, often of the tricuspid valve in people who inject drugs","osteomyelitis","septic arthritis","pneumonia, especially after influenza","toxic shock syndrome","staphylococcal scalded skin syndrome","food poisoning with vomiting within hours"],"diagnosis":["Gram stain and culture of blood, pus or tissue","catalase and coagulase tests","mecA gene PCR or susceptibility testing for MRSA"],"treatment":["MSSA: nafcillin, oxacillin or cefazolin","MRSA bacteremia: vancomycin or daptomycin (daptomycin not for pneumonia)","MRSA pneumonia or skin infection: linezolid is also an option","drain abscesses","remove infected lines and devices"],"prevention":["hand hygiene","nasal mupirocin decolonization before some surgeries"]}'::jsonb),
  ('statins', 1, 'in_review', null, null, '{"kind":"drug","name":"Statins","aliases":["HMG-CoA reductase inhibitors"],"systems":["cardio"],"rotation":[],"confused_with":[],"pearls":["High-intensity statin therapy (atorvastatin 40 to 80 mg or rosuvastatin 20 to 40 mg) lowers LDL by 50% or more.","Short-acting statins such as simvastatin work best taken in the evening, when the liver makes most of its cholesterol.","Gemfibrozil with a statin carries a much higher risk of myopathy than fenofibrate."],"difficulty_tiers":{"MS1-2":["class","mechanism"],"MS3":["indications","adverse_effects"],"MS4":["interactions","pearls[0]"]},"anki_refs":[],"sources":[{"title":"Katzung''s Basic and Clinical Pharmacology"},{"title":"Goodman & Gilman''s The Pharmacological Basis of Therapeutics"},{"title":"2018 AHA/ACC Guideline on the Management of Blood Cholesterol"}],"class":"HMG-CoA reductase inhibitors","class_members":["atorvastatin","rosuvastatin","simvastatin","pravastatin","lovastatin","pitavastatin","fluvastatin"],"mechanism":"Inhibit HMG-CoA reductase, the rate-limiting enzyme of cholesterol synthesis in the liver. Liver cells respond by making more LDL receptors, which pull LDL out of the blood. LDL falls most; triglycerides fall a little and HDL rises a little.","pharmacokinetics":["simvastatin, lovastatin and atorvastatin are metabolized by CYP3A4","rosuvastatin and pravastatin depend little on CYP3A4"],"indications":["established atherosclerotic cardiovascular disease","LDL of 190 mg/dL or higher","diabetes in adults aged 40 to 75","high 10-year cardiovascular risk"],"adverse_effects":["muscle aches","myopathy","rhabdomyolysis, rarely","raised liver enzymes","a small rise in the risk of diabetes"],"contraindications":["active liver disease","pregnancy and breastfeeding, for most patients"],"interactions":["CYP3A4 inhibitors such as clarithromycin, azole antifungals and grapefruit juice raise levels and the risk of myopathy","gemfibrozil raises the risk of myopathy"],"monitoring":["lipid panel 4 to 12 weeks after starting","liver enzymes at baseline","CK only if muscle symptoms appear"],"overdose":{"features":[],"treatment":[]}}'::jsonb),
  ('upper-gi-bleeding', 1, 'in_review', null, null, '{"kind":"disease","name":"Upper gastrointestinal bleeding","aliases":["upper GI bleed","UGIB"],"systems":["gi"],"rotation":["IM","EM","surgery"],"confused_with":[],"pearls":["In suspected variceal bleeding, give octreotide and antibiotics before endoscopy; antibiotics reduce infection and death."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1531907221280"},{"kind":"note","id":"1535752586086"},{"kind":"note","id":"1543178936469"},{"kind":"note","id":"1543191124336"},{"kind":"note","id":"1550842808822"}],"sources":[{"title":"ACG Clinical Guideline: Upper Gastrointestinal and Ulcer Bleeding (2021)"},{"title":"Baveno VII: Renewing consensus in portal hypertension (2022)"}],"epidemiology":{"who":"Adults; peptic ulcer disease is the most common cause","risk_factors":["peptic ulcer disease","esophageal varices","NSAIDs","Helicobacter pylori","anticoagulants","Mallory-Weiss tear"]},"pathophysiology":"Bleeding above the ligament of Treitz, most often from a peptic ulcer eroding a vessel, or from varices in portal hypertension.","timeline":{"onset":"Acute","course":"Most bleeds stop on their own; rebleeding raises mortality"},"key_findings":{"history":["hematemesis or coffee-ground vomit","melena","lightheadedness or syncope","NSAID or alcohol use"],"exam":["tachycardia and hypotension","signs of chronic liver disease in variceal bleeding"],"labs":["falling hemoglobin","raised BUN-to-creatinine ratio from digested blood"],"imaging":[]},"diagnosis":{"confirmatory_tests":["upper endoscopy within 24 hours"],"criteria":["the Glasgow-Blatchford score identifies low-risk patients for outpatient care"]},"management":{"first_line":["two large-bore IV lines and fluid resuscitation","transfuse to a hemoglobin of 7 g/dL (8 with cardiovascular disease)","IV proton pump inhibitor","upper endoscopy within 24 hours"],"next_line":["for varices: octreotide and antibiotics (ceftriaxone) before endoscopy, then band ligation","test for and treat Helicobacter pylori"]},"complications":["hemorrhagic shock","rebleeding","death"]}'::jsonb),
  ('viridans-streptococci', 1, 'in_review', null, null, '{"kind":"bug","name":"Viridans group streptococci","aliases":["viridans streptococci","Streptococcus viridans"],"systems":["cardio","general"],"rotation":[],"confused_with":[{"script_id":"staphylococcus-aureus","how_to_tell_apart":"Viridans streptococci grow in chains, are catalase-negative and cause subacute endocarditis over weeks, often after dental work; S. aureus grows in clusters, is coagulase-positive and causes acute endocarditis over days.","compare":[{"label":"Gram stain","text":"Cocci in chains","source_field":"morphology"},{"label":"Course","text":"Subacute endocarditis","source_field":"diseases[0]"},{"label":"Key test","text":"Catalase-negative","source_field":"lab_features[1]"}]},{"script_id":"enterococcus","how_to_tell_apart":"Both cause subacute endocarditis. Viridans streptococci are alpha-hemolytic, come from the mouth and follow dental work; enterococci grow in 6.5% salt, come from the gut and urinary tract and follow GI or urinary procedures.","compare":[{"label":"Gram stain","text":"Cocci in chains","source_field":"morphology"},{"label":"Source","text":"Mouth flora","source_field":"transmission[0]"},{"label":"Key test","text":"Alpha-hemolytic","source_field":"lab_features[0]"}]}],"pearls":["Viridans streptococci and S. pneumoniae are both alpha-hemolytic; optochin resistance and no bile solubility mark viridans.","Subacute endocarditis from viridans streptococci typically follows dental work and causes weeks of low fever and weight loss.","S. mutans uses sucrose to make dextran, which glues it to teeth."],"difficulty_tiers":{"MS1-2":["morphology","lab_features","virulence_factors"],"MS3":["diseases[0]","treatment"],"MS4":["prevention[1]"]},"anki_refs":[],"sources":[{"title":"Sherris & Ryan''s Medical Microbiology"},{"title":"2023 ESC Guidelines for the management of endocarditis"},{"title":"Prevention of Viridans Group Streptococcal Infective Endocarditis: A Scientific Statement From the American Heart Association (2021)"}],"morphology":"Gram-positive cocci in chains","lab_features":["alpha-hemolytic (green, partial hemolysis)","catalase-negative","optochin-resistant","not bile-soluble"],"transmission":["normal flora of the mouth","enter the blood after dental procedures or with poor dental hygiene"],"virulence_factors":["dextran, which helps them stick to fibrin and platelets on damaged valves","Streptococcus mutans makes acid that causes dental caries"],"diseases":["subacute endocarditis on damaged or abnormal valves","dental caries (S. mutans)","brain and liver abscesses (S. anginosus group)"],"diagnosis":["blood cultures","echocardiogram for endocarditis","alpha hemolysis and optochin resistance in the lab"],"treatment":["endocarditis: penicillin G or ceftriaxone, guided by penicillin susceptibility","gentamicin may be added for less susceptible strains"],"prevention":["good dental hygiene","amoxicillin before dental work for the highest-risk patients, including those with a prosthetic valve or prosthetic material used for valve repair, prior endocarditis, unrepaired cyanotic congenital heart disease, recently repaired congenital heart disease with prosthetic material, or a heart transplant with valve disease"]}'::jsonb);
insert into public.questions (id, script_id, script_version, rung, content) values
  ('zorblax-syndrome.recall.1', 'zorblax-syndrome', 1, 'recall', '{"prompt":"An adult has purple fatigue, itchy elbows and blue nail beds. Most likely diagnosis?","source_fields":["name"],"accepted_answers":[{"answer":"Zorblax syndrome","synonyms":["zorblax","ZBX"]}],"kind":"single"}'::jsonb),
  ('zorblax-syndrome.second-order.1', 'zorblax-syndrome', 1, 'second_order', '{"prompt":"Name 3 risk factors for Zorblax syndrome.","source_fields":["epidemiology.risk_factors"],"accepted_answers":[{"answer":"glimmer exposure","synonyms":["glimmer"]},{"answer":"night shift work","synonyms":["night shift","shift work"]},{"answer":"low blorp diet","synonyms":["low blorp"]},{"answer":"family history","synonyms":["family hx","genetics"]}],"kind":"list","required_count":3}'::jsonb),
  ('zorblax-syndrome.differentiate.1', 'zorblax-syndrome', 1, 'differentiate', '{"prompt":"On exam, how do you tell it apart from Quellan fever?","source_fields":["key_findings.exam","confused_with[0].how_to_tell_apart"],"accepted_answers":[{"answer":"blue nail beds","synonyms":["blue nails"]},{"answer":"green nail beds","synonyms":["green nails"]}],"kind":"single"}'::jsonb),
  ('zorblax-syndrome.workup.1', 'zorblax-syndrome', 1, 'workup', '{"prompt":"What test confirms the diagnosis?","source_fields":["diagnosis.confirmatory_tests"],"accepted_answers":[{"answer":"anti-glimmer antibody","synonyms":["anti glimmer","glimmer antibody"]}],"kind":"single"}'::jsonb),
  ('zorblax-syndrome.management.1', 'zorblax-syndrome', 1, 'management', '{"prompt":"First-line treatment?","source_fields":["management.first_line"],"accepted_answers":[{"answer":"zorbicillin","synonyms":[]}],"kind":"single"}'::jsonb),
  ('zorblax-syndrome.pearl.1', 'zorblax-syndrome', 1, 'pearl', '{"prompt":"Which vital-sign finding argues against Zorblax syndrome?","source_fields":["pearls[0]"],"accepted_answers":[{"answer":"fever","synonyms":["febrile","high temperature"]}],"kind":"single"}'::jsonb),
  ('zorblax-syndrome.management.2', 'zorblax-syndrome', 1, 'management', '{"prompt":"Zorbicillin has failed. What next?","source_fields":["management.next_line"],"accepted_answers":[{"answer":"plasma swap","synonyms":["plasma exchange"]}],"kind":"single"}'::jsonb),
